function displayComplianceFileTwoQueueKey(entry) {
  return [entry?.customer || "", entry?.activityType || "", entry?.siebelId || entry?.priority || ""].map(displayComplianceNormalizedName).join("\u0001");
}

function nextDisplayComplianceCursor(batch, run) {
  const customerIndex = Number(run.displayComplianceCustomerIndex || 0);
  const activityIndex = Number(run.displayComplianceActivityIndex || 0);
  const page = Number(run.displayCompliancePage || 0);
  const priorityIndex = Number(run.displayCompliancePriorityIndex || 0);
  const pageRows = Math.max(0, Number(run.displayCompliancePageRows || 0));
  const pageEnd = Math.max(0, Number(run.displayCompliancePageEnd || 0));
  const totalRecords = Math.max(0, Number(run.displayComplianceTotalRecords || 0));
  if (pageRows > priorityIndex + 1) return { customerIndex, activityIndex, page, priorityIndex: priorityIndex + 1 };
  if (pageEnd > 0 && totalRecords > pageEnd) return { customerIndex, activityIndex, page: page + 1, priorityIndex: 0 };
  if (activityIndex + 1 < batch.activities.length) return { customerIndex, activityIndex: activityIndex + 1, page: 0, priorityIndex: 0 };
  if (customerIndex + 1 < batch.customerQueue.length) return { customerIndex: customerIndex + 1, activityIndex: 0, page: 0, priorityIndex: 0 };
  return null;
}

async function advanceDisplayComplianceBatch(batchId, runId) {
  if (!batchId) return;
  const batchRef = db.collection("displayComplianceBatches").doc(batchId);
  const runRef = db.collection("extractionRuns").doc(runId);
  await db.runTransaction(async (transaction) => {
    const [batchDoc, runDoc] = await Promise.all([transaction.get(batchRef), transaction.get(runRef)]);
    if (!batchDoc.exists || !runDoc.exists) return;
    const batch = batchDoc.data();
    const run = runDoc.data();
    if (batch.currentRunId !== runId) return;
    if (batch.status === "cancelled" || run.status === "cancelled") {
      transaction.update(batchRef, { status: "cancelled", currentRunId: null, completedAt: FieldValue.serverTimestamp() });
      return;
    }
    if (run.workflowMode === "salesforce-display-compliance-file1-discover") {
      if (run.status !== "completed") {
        transaction.update(batchRef, {
          status: "needs_attention", currentRunId: null,
          message: "Customer discovery did not complete. Review the discovery run before restarting.",
          failedCount: Number(batch.failedCount || 0) + 1,
          completedAt: FieldValue.serverTimestamp()
        });
        return;
      }
      const customers = [...new Set((run.displayComplianceCustomers || []).map((value) => optionalText(value, 160)).filter(Boolean))];
      if (!customers.length) {
        transaction.update(batchRef, {
          status: "needs_attention", currentRunId: null,
          message: "Salesforce returned no Display Compliance customers.",
          failedCount: Number(batch.failedCount || 0) + 1,
          completedAt: FieldValue.serverTimestamp()
        });
        return;
      }
      const nextRunRef = db.collection("extractionRuns").doc();
      const nextBatch = { ...batch, customerQueue: customers, totalCustomers: customers.length, activities: batch.activities?.length ? batch.activities : salesforceDisplayComplianceActivities };
      transaction.set(nextRunRef, displayComplianceChildRunData(nextBatch, { customerIndex: 0, activityIndex: 0, page: 0, priorityIndex: 0 }));
      transaction.update(batchRef, {
        customerQueue: customers,
        activities: nextBatch.activities,
        totalCustomers: customers.length,
        status: "running",
        stage: "extracting-file-1",
        currentRunId: nextRunRef.id,
        currentCustomerIndex: 0,
        currentActivityIndex: 0,
        currentPage: 0,
        currentPriorityIndex: 0,
        currentCustomerName: customers[0],
        currentActivityType: nextBatch.activities[0],
        message: `Processing ${customers[0]}: ${nextBatch.activities[0]} File 1 priorities.`
      });
      return;
    }
    if (run.workflowMode === "salesforce-display-compliance-file2") {
      if (!["completed", "completed_no_data"].includes(run.status)) {
        transaction.update(batchRef, {
          status: "needs_attention",
          stage: "file-2-failed",
          currentRunId: null,
          file2RunId: runId,
          failedCount: Number(batch.failedCount || 0) + 1,
          message: `ZA POP Topsheet File 2 did not complete: ${String(run.message || "review the File 2 run").slice(0, 300)}`,
          completedAt: FieldValue.serverTimestamp()
        });
        return;
      }
      const fileTwoQueue = Array.isArray(batch.fileTwoQueue) ? batch.fileTwoQueue : [];
      const nextIndex = Number(run.displayComplianceFileTwoQueueIndex || 0) + 1;
      const file2NoDataCount = Number(batch.file2NoDataCount || 0) + (run.noData ? 1 : 0);
      if (nextIndex < fileTwoQueue.length) {
        const nextRunRef = db.collection("extractionRuns").doc();
        const nextRun = displayComplianceFileTwoRunData(batch, fileTwoQueue[nextIndex], nextIndex);
        transaction.set(nextRunRef, nextRun);
        transaction.update(batchRef, {
          status: "running",
          stage: "extracting-file-2",
          currentRunId: nextRunRef.id,
          file2RunId: nextRunRef.id,
          file2NoDataCount,
          currentFileTwoIndex: nextIndex,
          message: `Downloading File 2 ${nextIndex + 1} of ${fileTwoQueue.length}: ${nextRun.displayComplianceCustomer} - ${nextRun.displayCompliancePriority || nextRun.displayComplianceSiebelId}.`
        });
        return;
      }
      const issueRunRef = db.collection("extractionRuns").doc();
      const issueRun = displayComplianceIssueTrackingRunData(batch);
      transaction.set(issueRunRef, issueRun);
      transaction.update(batchRef, {
        status: "running",
        stage: "extracting-issue-tracking",
        currentRunId: issueRunRef.id,
        file2RunId: runId,
        file2FileId: run.fileId || null,
        file2NoDataCount,
        issueTrackingRunId: issueRunRef.id,
        message: `${Number(batch.deliveredCount || 0)} File 1 reports saved. ZA POP Topsheet File 2 completed for ${Math.max(0, fileTwoQueue.length - file2NoDataCount)} priorities${file2NoDataCount ? `; ${file2NoDataCount} priorities returned no ZA POP Actual row` : ""}. Downloading Issue Tracking next.`
      });
      return;
    }
    if (run.workflowMode === "salesforce-display-compliance-issue-tracking") {
      if (run.status !== "completed") {
        transaction.update(batchRef, {
          status: "needs_attention",
          stage: "issue-tracking-failed",
          currentRunId: null,
          issueTrackingRunId: runId,
          failedCount: Number(batch.failedCount || 0) + 1,
          message: `Issue Tracking did not complete: ${String(run.message || "review the Issue Tracking run").slice(0, 300)}`,
          completedAt: FieldValue.serverTimestamp()
        });
        return;
      }
      const fileTwoQueue = Array.isArray(batch.fileTwoQueue) ? batch.fileTwoQueue : [];
      const file2NoDataCount = Number(batch.file2NoDataCount || 0);
      transaction.update(batchRef, {
        status: batch.failedCount ? "completed_with_errors" : "completed",
        stage: "completed",
        currentRunId: null,
        issueTrackingRunId: runId,
        issueTrackingFileId: run.fileId || null,
        message: `${Number(batch.deliveredCount || 0)} File 1 reports saved. ZA POP Topsheet File 2 completed for ${Math.max(0, fileTwoQueue.length - file2NoDataCount)} priorities${file2NoDataCount ? `; ${file2NoDataCount} priorities returned no ZA POP Actual row` : ""}. Issue Tracking completed and Phase Two can now validate all sources.`,
        completedAt: FieldValue.serverTimestamp()
      });
      return;
    }
    if (run.status === "failed") {
      transaction.update(batchRef, {
        status: "needs_attention", currentRunId: null,
        failedCount: Number(batch.failedCount || 0) + 1,
        message: `Stopped at ${run.displayComplianceCustomer || "the current customer"}: ${String(run.message || "the priority could not be extracted").slice(0, 300)}`,
        completedAt: FieldValue.serverTimestamp()
      });
      return;
    }
    const currentPriorityFound = Boolean(run.displayCompliancePriority || run.displayComplianceSiebelId);
    const deliveredCount = Number(batch.deliveredCount || 0) + (run.fileId && !run.isDuplicate ? 1 : 0);
    const duplicateCount = Number(batch.duplicateCount || 0) + (run.isDuplicate ? 1 : 0);
    const noDataCount = Number(batch.noDataCount || 0) + (run.noData ? 1 : 0);
    const totalPriorities = Number(batch.totalPriorities || 0) + (currentPriorityFound ? 1 : 0);
    const existingFileTwoQueue = Array.isArray(batch.fileTwoQueue) ? batch.fileTwoQueue : [];
    // File 1 and ZA POP File 2 are independent Salesforce exports. A File 1
    // placeholder is not evidence that ZA POP has no Actual data, particularly
    // for priorities which begin in the selected month and finish in the next.
    // Queue File 2 for every priority discovered in the File 1 grid.
    const currentFileTwo = ["completed", "completed_no_data"].includes(run.status)
      ? displayComplianceFileTwoQueueEntry(run)
      : null;
    const fileTwoQueue = currentFileTwo && !existingFileTwoQueue.some((entry) => displayComplianceFileTwoQueueKey(entry) === displayComplianceFileTwoQueueKey(currentFileTwo))
      ? [...existingFileTwoQueue, currentFileTwo]
      : existingFileTwoQueue;
    const nextCursor = nextDisplayComplianceCursor(batch, run);
    if (!nextCursor) {
      if (!fileTwoQueue.length) {
        transaction.update(batchRef, {
          status: "needs_attention",
          stage: "file-2-not-queued",
          currentRunId: null,
          deliveredCount,
          duplicateCount,
          noDataCount,
          totalPriorities,
          message: "File 1 completed without a scoped priority to drive File 2. The batch was not marked complete."
        });
        return;
      }
      const fileTwoRunRef = db.collection("extractionRuns").doc();
      const fileTwoRun = displayComplianceFileTwoRunData(batch, fileTwoQueue[0], 0);
      transaction.set(fileTwoRunRef, fileTwoRun);
      transaction.update(batchRef, {
        status: "running",
        stage: "extracting-file-2",
        currentRunId: fileTwoRunRef.id,
        file2RunId: fileTwoRunRef.id,
        deliveredCount,
        duplicateCount,
        noDataCount,
        totalPriorities,
        fileTwoQueue,
        currentFileTwoIndex: 0,
        message: `${deliveredCount} File 1 reports saved${duplicateCount ? `; ${duplicateCount} existing files reused` : ""}${noDataCount ? `; ${noDataCount} customer/activity filters returned no priorities` : ""}. Downloading ${fileTwoQueue.length} scoped ZA POP Topsheet File 2 report${fileTwoQueue.length === 1 ? "" : "s"} next.`
      });
      return;
    }
    const nextRunRef = db.collection("extractionRuns").doc();
    const nextRun = displayComplianceChildRunData(batch, nextCursor);
    transaction.set(nextRunRef, nextRun);
    transaction.update(batchRef, {
      status: "running",
      currentRunId: nextRunRef.id,
      currentCustomerIndex: nextCursor.customerIndex,
      currentActivityIndex: nextCursor.activityIndex,
      currentPage: nextCursor.page,
      currentPriorityIndex: nextCursor.priorityIndex,
      currentCustomerName: nextRun.displayComplianceCustomer,
      currentActivityType: nextRun.displayComplianceActivityType,
      deliveredCount,
      duplicateCount,
      noDataCount,
      totalPriorities,
      fileTwoQueue,
      message: `Processing ${nextRun.displayComplianceCustomer}: ${nextRun.displayComplianceActivityType}, page ${nextCursor.page + 1}, priority ${nextCursor.priorityIndex + 1}.`
    });
  });
}

// A terminal File 1 worker can occasionally complete while its Firestore
// coordinator event is delayed. Never leave a completed batch without the
// mandatory ZA POP Topsheet (File 2): the status trigger below can recover the
// final File 1 cursor and queue the missing child exactly once.
async function recoverIncompleteDisplayComplianceBatch(batchId, runId) {
  if (!batchId || !runId) return { recovered: false, reason: "missing-batch-or-run" };
  const batchRef = db.collection("displayComplianceBatches").doc(batchId);
  const runRef = db.collection("extractionRuns").doc(runId);
  let result = { recovered: false, reason: "not-required" };
  await db.runTransaction(async (transaction) => {
    const [batchDoc, runDoc] = await Promise.all([transaction.get(batchRef), transaction.get(runRef)]);
    if (!batchDoc.exists || !runDoc.exists) {
      result = { recovered: false, reason: "missing-record" };
      return;
    }
    const batch = batchDoc.data();
    const run = runDoc.data();
    if (batch.retailerId !== salesforceDisplayComplianceRetailerId
      || !["salesforce-display-compliance-file1-discover", "salesforce-display-compliance-file1"].includes(run.workflowMode)
      || run.status !== "completed") {
      result = { recovered: false, reason: "not-a-terminal-file-one-run" };
      return;
    }
    if (batch.file2RunId || batch.currentRunId) {
      result = { recovered: false, reason: "file-two-or-next-run-already-queued" };
      return;
    }
    if (!["completed", "completed_with_errors"].includes(batch.status)) {
      result = { recovered: false, reason: "batch-is-still-active" };
      return;
    }
    const nextCursor = run.workflowMode === "salesforce-display-compliance-file1-discover"
      ? null
      : nextDisplayComplianceCursor(batch, run);
    if (nextCursor) {
      const nextRunRef = db.collection("extractionRuns").doc();
      const nextRun = displayComplianceChildRunData(batch, nextCursor);
      transaction.set(nextRunRef, nextRun);
      transaction.update(batchRef, {
        status: "running",
        stage: "extracting-file-1",
        currentRunId: nextRunRef.id,
        currentCustomerIndex: nextCursor.customerIndex,
        currentActivityIndex: nextCursor.activityIndex,
        currentPage: nextCursor.page,
        currentPriorityIndex: nextCursor.priorityIndex,
        currentCustomerName: nextRun.displayComplianceCustomer,
        currentActivityType: nextRun.displayComplianceActivityType,
        message: "Recovering the next pending File 1 priority before ZA POP Topsheet File 2."
      });
      result = { recovered: true, stage: "file-1", runId: nextRunRef.id };
      return;
    }
    const fileTwoQueue = Array.isArray(batch.fileTwoQueue) ? batch.fileTwoQueue : [];
    if (!fileTwoQueue.length) {
      transaction.update(batchRef, {
        status: "needs_attention",
        stage: "file-2-not-queued",
        currentRunId: null,
        message: "The legacy File 1 batch has no scoped priority list for File 2. Start a fresh Display Compliance run; Nexus will not copy one generic File 2 export to all customers."
      });
      result = { recovered: false, reason: "missing-file-two-scope" };
      return;
    }
    const fileTwoRunRef = db.collection("extractionRuns").doc();
    const fileTwoRun = displayComplianceFileTwoRunData(batch, fileTwoQueue[0], 0);
    transaction.set(fileTwoRunRef, fileTwoRun);
    transaction.update(batchRef, {
      status: "running",
      stage: "extracting-file-2",
      currentRunId: fileTwoRunRef.id,
      file2RunId: fileTwoRunRef.id,
      currentFileTwoIndex: 0,
      message: "Recovering the first scoped ZA POP Topsheet File 2 after File 1 completed."
    });
    result = { recovered: true, stage: "file-2", runId: fileTwoRunRef.id };
  });
  return result;
}

async function openSalesforceDisplayComplianceWorkspace({ page, retailer, steps, run, runRef, runId, downloadDir }) {
  let workspaceOpened = false;
  for (let index = 0; index < steps.length; index += 1) {
    const step = steps[index];
    if (step.action === "salesforceInspectWorkspace") break;
    await ensureExtractionActive(runRef);
    await runRef.set({
      status: "running",
      currentStep: index + 1,
      totalSteps: steps.length,
      currentStepAction: step.action,
      message: `Preparing Salesforce: step ${index + 1} of ${steps.length} (${step.action}).`,
      lastActivityAt: FieldValue.serverTimestamp(),
      executionTimeline: FieldValue.arrayUnion(runTimelineEvent("step-started", `Step ${index + 1}: ${step.action}`, { step: index + 1, action: step.action }))
    }, { merge: true });
    await runStep(page, step, retailer, downloadDir, run, { runRef, runId, stepNumber: index + 1 });
    const resumedAfterSalesforceApproval = await resolveSalesforceMidWorkflowVerification(
      page,
      retailer,
      run,
      { runRef, runId, stepNumber: index + 1, stepAction: step.action }
    );
    if (resumedAfterSalesforceApproval) {
      await appendRunTimeline(
        runRef,
        "salesforce-display-compliance-mid-workflow-resumed",
        `Salesforce approved the additional verification after step ${index + 1}; continuing Display Compliance.`,
        { step: index + 1, action: step.action }
      );
    }
    await appendRunTimeline(runRef, "step-completed", `Step ${index + 1}: ${step.action} completed.`, { step: index + 1, action: step.action });
    if (step.action === "fillOtp") await saveSalesforceSession(page, salesforceSessionKeyForRetailer(run.retailerId, retailer));
    if (step.action === "salesforceOpenWorkspace") {
      workspaceOpened = true;
      break;
    }
  }
  if (!workspaceOpened) throw new Error("The Salesforce Display Compliance workspace step is not configured.");
}

async function salesforceExportDisplayComplianceWorkbook(page, downloadDir, run, context = {}) {
  await context.runRef?.set({
    message: "Exporting the Salesforce Display Compliance workbook from the current filtered report view.",
    lastActivityAt: FieldValue.serverTimestamp()
  }, { merge: true }).catch(() => {});
  const startedAt = Date.now();
  let downloaded;
  try {
    const exportWait = waitForSalesforceExport(page, downloadDir, startedAt, 150000);
    await triggerNativeSalesforceExport(page);
    downloaded = await exportWait;
  } catch (error) {
    if (!(error instanceof SalesforceExportVerificationRequiredError)) throw error;
    const verificationPage = await findSalesforceExportVerificationPage(page);
    await completeSalesforceExportVerification(verificationPage, run, context);
    await appendRunTimeline(
      context.runRef,
      "salesforce-display-compliance-export-approval",
      "Salesforce approved the Display Compliance export; waiting for the report download to resume.",
      { step: context.stepNumber || null }
    ).catch(() => {});
    let resumeError = null;
    try {
      downloaded = await waitForSalesforceExport(page, downloadDir, startedAt, 60000, [verificationPage]);
    } catch (resumeError) {
      if (resumeError instanceof SalesforceExportVerificationRequiredError) {
        await appendRunTimeline(
          context.runRef,
          "salesforce-display-compliance-second-export-approval-required",
          "Salesforce requested one additional approval while resuming the Display Compliance export. Nexus will wait for that approval once.",
          { step: context.stepNumber || null }
        ).catch(() => {});
        const secondVerificationPage = await findSalesforceExportVerificationPage(page);
        await completeSalesforceExportVerification(secondVerificationPage, run, context);
        const secondStartedAt = Date.now();
        try {
          downloaded = await waitForSalesforceExport(page, downloadDir, secondStartedAt, 60000, [verificationPage, secondVerificationPage]);
        } catch (secondApprovalError) {
          if (secondApprovalError instanceof SalesforceExportVerificationRequiredError) {
            throw new Error("Salesforce requested more than two Display Compliance export approvals. Nexus stopped to protect the account; wait before starting one fresh extraction.");
          }
          resumeError = secondApprovalError;
        }
      }
    }
    if (!downloaded) {
      await appendRunTimeline(
        context.runRef,
        "salesforce-display-compliance-export-retry",
        "Salesforce accepted approval but did not resume the download; replaying the Display Compliance export once.",
        { step: context.stepNumber || null, reason: String(resumeError?.message || resumeError || "download did not resume").slice(0, 240) }
      ).catch(() => {});
      const retryStartedAt = Date.now();
      const retryWait = waitForSalesforceExport(page, downloadDir, retryStartedAt, 150000, [verificationPage]);
      await triggerNativeSalesforceExport(page);
      downloaded = await retryWait;
    }
  }
  await verifyDisplayComplianceDownload(downloaded);
  return downloaded;
}

async function completeExistingDisplayComplianceDelivery({ runRef, run, runId, reservation, destination }) {
  const fileDoc = await db.collection("files").doc(reservation.fileId).get();
  if (!fileDoc.exists) throw new Error("The completed Display Compliance delivery record has no file to reuse.");
  const file = { id: fileDoc.id, ...fileDoc.data() };
  const groupName = optionalText(run.displayComplianceFileGroup || file.displayComplianceFileGroup, 80) || "Display Compliance";
  if (destination && (file.sharePoint?.status !== "uploaded" || file.sharePoint?.folderPath !== destination.folderPath)) {
    const uploaded = await redeliverStoredFileToSharePoint(file, destination);
    file.sharePoint = { ...uploaded, uploadedAt: FieldValue.serverTimestamp() };
    await fileDoc.ref.set({ sharePoint: file.sharePoint }, { merge: true });
  }
  await runRef.set({
    status: "completed",
    isDuplicate: true,
    fileId: file.id,
    fileName: file.name || file.originalName || null,
    fileSize: file.size || null,
    storagePath: file.storagePath || null,
    sharePoint: file.sharePoint || null,
    reportIdentity: reservation.reportIdentity,
    message: `${file.name || groupName} already exists and was reused without another Salesforce download.`,
    completedAt: FieldValue.serverTimestamp(),
    executionTimeline: FieldValue.arrayUnion(runTimelineEvent("duplicate-reused", `Reused the verified ${groupName} report already stored for this date range.`))
  }, { merge: true });
}

async function processSalesforceDisplayComplianceFileTwoRun(event) {
  const runRef = event.data.ref;
  const run = event.data.data();
  const runId = event.params.runId;
  let browser;
  let page;
  let downloadDir = "";
  let salesforceSessionKey = "";
  let salesforceBrowserLease = null;
  const reportIdentity = displayComplianceFileTwoIdentity(run);
  try {
    await ensureExtractionActive(runRef);
    const [retailer, extractionProfile, configDocument] = await Promise.all([
      loadRetailerAutomation(run.retailerId),
      run.extractionProfileId ? loadExtractionProfile(run.extractionProfileId) : Promise.resolve(null),
      db.collection("salesforceDisplayComplianceConfig").doc("current").get()
    ]);
    const config = configDocument.exists ? configDocument.data() : {};
    const steps = extractionProfile?.steps || retailer.steps;
    if (!Array.isArray(steps) || !steps.length) throw new Error("Display Compliance has no linked Salesforce workflow steps.");
    salesforceSessionKey = salesforceSessionKeyForRetailer(run.retailerId, retailer);
    salesforceBrowserLease = await acquireSalesforceBrowserLease(salesforceSessionKey || run.retailerId, runId, runRef, run.retailerName);
    await runRef.set({
      status: "running",
      stage: "restoring-session",
      reportIdentity,
      message: "Restoring Salesforce to download ZA POP Topsheet File 2.",
      startedAt: FieldValue.serverTimestamp(),
      lastActivityAt: FieldValue.serverTimestamp(),
      executionTimeline: FieldValue.arrayUnion(runTimelineEvent("started", "Started ZA POP Topsheet File 2 extraction."))
    }, { merge: true });
    downloadDir = await fs.mkdtemp(path.join(os.tmpdir(), "nexus-display-compliance-file2-"));
    const launched = await launchAutomationBrowser(downloadDir);
    browser = launched.browser;
    page = launched.page;
    const restored = await restoreSalesforceSession(page, salesforceSessionKey || run.retailerId);
    if (restored) {
      retailer.salesforceSessionOrigin = typeof restored === "string" ? restored : "";
      await appendRunTimeline(runRef, "salesforce-session-restored", "A recent encrypted Salesforce session was restored before the ZA POP Topsheet download.");
    }
    await openSalesforceDisplayComplianceWorkspace({ page, retailer, steps, run, runRef, runId, downloadDir });
    await runRef.set({ stage: "opening-za-pop-topsheet", message: `Opening ZA POP Topsheet for ${run.displayComplianceCustomer}: ${run.displayCompliancePriority || run.displayComplianceSiebelId}.`, lastActivityAt: FieldValue.serverTimestamp() }, { merge: true });
    await salesforceOpenZaPopTopsheet(page, retailer.salesforceSessionOrigin || "");
    await runRef.set({ stage: "selecting-za-pop-date-range", message: `Returning ZA POP Topsheet to the date range screen for ${run.displayComplianceCustomer}: ${run.displayCompliancePriority || run.displayComplianceSiebelId}.`, lastActivityAt: FieldValue.serverTimestamp() }, { merge: true });
    await salesforceReturnToDisplayComplianceDateRange(page, retailer.salesforceSessionOrigin || "");
    await salesforceConfigureDisplayCompliance(page, run, "");
    await salesforceOpenZaPopTopsheetPriority(page, {
      siebelId: run.displayComplianceSiebelId,
      name: run.displayCompliancePriority
    });
    await runRef.set({ stage: "exporting-za-pop-topsheet", message: `Exporting ZA POP Topsheet for ${run.displayComplianceCustomer}: ${run.displayCompliancePriority || run.displayComplianceSiebelId}.`, lastActivityAt: FieldValue.serverTimestamp() }, { merge: true });
    const downloaded = await salesforceExportDisplayComplianceWorkbook(page, downloadDir, run, { runRef, runId, stepNumber: null });
    const verifiedStat = await verifyDisplayComplianceDownload(downloaded);
    const sha256 = await hashFile(downloaded.filePath);
    const extension = path.extname(downloaded.name || "") || ".xlsx";
    const safeName = displayComplianceFileTwoName(run, downloaded.name);
    const fileId = crypto.randomUUID();
    const storagePath = `uploads/${fileId}/${safeName}`;
    const [storedFile] = await getStorage().bucket().upload(downloaded.filePath, {
      destination: storagePath,
      metadata: {
        contentType: extension.toLowerCase() === ".csv" ? "text/csv" : "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        metadata: { extractionRunId: runId, retailerId: run.retailerId, reportIdentity, sha256 }
      }
    });
    const [storedMetadata] = await storedFile.getMetadata();
    if (Number(storedMetadata.size) !== verifiedStat.size) {
      await storedFile.delete().catch(() => {});
      throw new Error("The ZA POP Topsheet Firebase Storage upload failed size verification.");
    }
    const destination = salesforceDisplayComplianceDestination({ ...run, displayComplianceFileGroup: "File 2" });
    const reservation = await reserveReportDelivery(runRef, runId, { ...run, displayComplianceFileGroup: "File 2" }, reportIdentity);
    if (reservation.state === "completed") {
      await completeExistingDisplayComplianceDelivery({ runRef, run, runId, reservation, destination });
      return;
    }
    if (reservation.state === "in-progress") throw new Error("An identical ZA POP Topsheet File 2 is already being extracted by another run.");
    const fileRef = db.collection("files").doc(fileId);
    await fileRef.set({
      name: safeName,
      originalName: String(downloaded.name || safeName),
      size: verifiedStat.size,
      type: extension.toLowerCase() === ".csv" ? "text/csv" : "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      storagePath,
      sha256,
      source: "salesforce-display-compliance-file2",
      retailerId: run.retailerId,
      retailerName: run.retailerName,
      extractionRunId: runId,
      extractionBatchId: run.displayComplianceBatchId,
      reportIdentity,
      reportStartDate: run.reportStartDate,
      reportEndDate: run.reportEndDate,
      displayComplianceFileGroup: "File 2",
      displayComplianceReportName: "ZA POP Topsheet",
      displayComplianceCustomer: run.displayComplianceCustomer,
      displayComplianceActivityType: run.displayComplianceActivityType,
      displayCompliancePriority: run.displayCompliancePriority || null,
      displayComplianceSiebelId: run.displayComplianceSiebelId || null,
      sharePoint: { provider: "sharepoint", status: "pending", folderPath: destination.folderPath },
      createdAt: FieldValue.serverTimestamp(),
      uploadedAt: FieldValue.serverTimestamp(),
      completedAt: FieldValue.serverTimestamp()
    });
    await runRef.set({ stage: "delivering", message: `Delivering ${safeName} to File 2 folders.`, lastActivityAt: FieldValue.serverTimestamp() }, { merge: true });
    const uploaded = await uploadFileToSharePoint(downloaded.filePath, safeName, verifiedStat.size, destination);
    const sharePoint = { ...uploaded, uploadedAt: FieldValue.serverTimestamp() };
    const workspaceCopies = await deliverDisplayComplianceWorkspaceCopies({
      filePath: downloaded.filePath,
      fileName: safeName,
      fileSize: verifiedStat.size,
      config,
      customer: run.displayComplianceCustomer,
      fileGroup: "File 2"
    });
    await fileRef.set({ sharePoint, workspaceCopies }, { merge: true });
    await saveSalesforceSession(page, salesforceSessionKey || run.retailerId);
    const deliveredCopies = workspaceCopies.filter((copy) => copy.status === "uploaded").length;
    const message = `${safeName} was verified and delivered to ${run.displayComplianceCustomer} File 2, with ${deliveredCopies}/${workspaceCopies.length} matching customer workspace ${workspaceCopies.length === 1 ? "copy" : "copies"}.`;
    await runRef.set({
      status: "completed",
      stage: "completed",
      fileId,
      fileName: safeName,
      fileSize: verifiedStat.size,
      fileSha256: sha256,
      storagePath,
      sharePoint,
      workspaceCopies,
      reportIdentity,
      message,
      completedAt: FieldValue.serverTimestamp(),
      lastActivityAt: FieldValue.serverTimestamp(),
      executionTimeline: FieldValue.arrayUnion(runTimelineEvent("completed", message, { fileId, fileName: safeName }))
    }, { merge: true });
    await updateReportDelivery(reportIdentity, { status: "completed", fileId, runId, fileName: safeName, storagePath });
  } catch (error) {
    console.error("Salesforce Display Compliance File 2 run failed", runId, error);
    if (isSalesforceRetailer(run.retailerId) && salesforceSessionWasInvalidated(error)) {
      await clearSalesforceSession(salesforceSessionKey || run.retailerId);
      await appendRunTimeline(runRef, "salesforce-session-cleared", "Salesforce invalidated the stored session. A fresh MFA approval is required before restarting File 2.");
    }
    const cancelled = error instanceof ExtractionCancelledError || await extractionCancellationRequested(runRef);
    if (!cancelled && isDisplayComplianceFileTwoNoData(error)) {
      const message = `ZA POP Topsheet returned no Actual row for ${run.displayComplianceCustomer}: ${run.displayCompliancePriority || run.displayComplianceSiebelId}. Nexus marked this File 2 priority as no-data and will continue the batch.`;
      await runRef.set({
        status: "completed_no_data",
        stage: "completed_no_data",
        noData: true,
        message,
        reportIdentity,
        completedAt: FieldValue.serverTimestamp(),
        lastActivityAt: FieldValue.serverTimestamp(),
        executionTimeline: FieldValue.arrayUnion(runTimelineEvent("completed_no_data", message))
      }, { merge: true });
      await updateReportDelivery(reportIdentity, { status: "completed_no_data", runId, message });
      return;
    }
    const message = cancelled
      ? "ZA POP Topsheet File 2 extraction was aborted."
      : String(error.message || error).slice(0, 500);
    await runRef.set({
      status: cancelled ? "cancelled" : "failed",
      stage: "failed",
      message,
      reportIdentity,
      completedAt: FieldValue.serverTimestamp(),
      lastActivityAt: FieldValue.serverTimestamp(),
      executionTimeline: FieldValue.arrayUnion(runTimelineEvent("failed", message))
    }, { merge: true });
    await updateReportDelivery(reportIdentity, { status: "failed", runId, message });
  } finally {
    if (browser) await browser.close().catch(() => {});
    if (downloadDir) await fs.rm(downloadDir, { recursive: true, force: true }).catch(() => {});
    await releaseSalesforceBrowserLease(salesforceBrowserLease, runId);
    await advanceDisplayComplianceBatch(run.displayComplianceBatchId, runId).catch((error) => console.error("Could not advance Display Compliance batch after File 2", run.displayComplianceBatchId, error));
  }
}

async function processSalesforceDisplayComplianceIssueTrackingRun(event) {
  const runRef = event.data.ref;
  const run = event.data.data();
  const runId = event.params.runId;
  let browser;
  let page;
  let downloadDir = "";
  let salesforceSessionKey = "";
  let salesforceBrowserLease = null;
  const reportIdentity = displayComplianceIssueTrackingIdentity(run);
  try {
    await ensureExtractionActive(runRef);
    const [retailer, extractionProfile] = await Promise.all([
      loadRetailerAutomation(run.retailerId),
      run.extractionProfileId ? loadExtractionProfile(run.extractionProfileId) : Promise.resolve(null)
    ]);
    const steps = extractionProfile?.steps || retailer.steps;
    if (!Array.isArray(steps) || !steps.length) throw new Error("Display Compliance has no linked Salesforce workflow steps.");
    salesforceSessionKey = salesforceSessionKeyForRetailer(run.retailerId, retailer);
    salesforceBrowserLease = await acquireSalesforceBrowserLease(salesforceSessionKey || run.retailerId, runId, runRef, run.retailerName);
    const issueDates = displayComplianceIssueTrackingDates(run);
    await runRef.set({
      status: "running",
      stage: "restoring-session",
      reportIdentity,
      message: `Restoring Salesforce to download Issue Tracking (${issueDates.startDate} to ${issueDates.endDate}).`,
      startedAt: FieldValue.serverTimestamp(),
      lastActivityAt: FieldValue.serverTimestamp(),
      executionTimeline: FieldValue.arrayUnion(runTimelineEvent("started", "Started Display Compliance Issue Tracking extraction."))
    }, { merge: true });
    downloadDir = await fs.mkdtemp(path.join(os.tmpdir(), "nexus-display-compliance-issue-"));
    const launched = await launchAutomationBrowser(downloadDir);
    browser = launched.browser;
    page = launched.page;
    const restored = await restoreSalesforceSession(page, salesforceSessionKey || run.retailerId);
    if (restored) {
      retailer.salesforceSessionOrigin = typeof restored === "string" ? restored : "";
      await appendRunTimeline(runRef, "salesforce-session-restored", "A recent encrypted Salesforce session was restored before the Issue Tracking download.");
    }
    await openSalesforceDisplayComplianceWorkspace({ page, retailer, steps, run, runRef, runId, downloadDir });
    await runRef.set({
      stage: "opening-issue-tracking",
      message: `Opening Issue Tracking Report - Meridian for ${issueDates.startDate} to ${issueDates.endDate}.`,
      lastActivityAt: FieldValue.serverTimestamp()
    }, { merge: true });
    await salesforceOpenReport(page, "Issue Tracking Report - Meridian", retailer.salesforceSessionOrigin || "", { runRef, runId });
    await runRef.set({
      stage: "exporting-issue-tracking",
      message: "Exporting Issue Tracking Report - Meridian.",
      lastActivityAt: FieldValue.serverTimestamp()
    }, { merge: true });
    const downloaded = await salesforceExportDisplayComplianceWorkbook(page, downloadDir, run, { runRef, runId, stepNumber: null });
    const verifiedStat = await verifyDisplayComplianceDownload(downloaded);
    const sha256 = await hashFile(downloaded.filePath);
    const extension = path.extname(downloaded.name || "") || ".xlsx";
    const safeName = displayComplianceIssueTrackingName(run, downloaded.name);
    const fileId = crypto.randomUUID();
    const storagePath = `uploads/${fileId}/${safeName}`;
    const [storedFile] = await getStorage().bucket().upload(downloaded.filePath, {
      destination: storagePath,
      metadata: {
        contentType: extension.toLowerCase() === ".csv" ? "text/csv" : "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        metadata: { extractionRunId: runId, retailerId: run.retailerId, reportIdentity, sha256 }
      }
    });
    const [storedMetadata] = await storedFile.getMetadata();
    if (Number(storedMetadata.size) !== verifiedStat.size) {
      await storedFile.delete().catch(() => {});
      throw new Error("The Issue Tracking Firebase Storage upload failed size verification.");
    }
    const destination = salesforceDisplayComplianceDestination({ ...run, displayComplianceFileGroup: "Issue Tracking" });
    const reservation = await reserveReportDelivery(runRef, runId, { ...run, displayComplianceFileGroup: "Issue Tracking" }, reportIdentity);
    if (reservation.state === "completed") {
      await completeExistingDisplayComplianceDelivery({ runRef, run, runId, reservation, destination });
      return;
    }
    if (reservation.state === "in-progress") throw new Error("An identical Issue Tracking report is already being extracted by another run.");
    const fileRef = db.collection("files").doc(fileId);
    await fileRef.set({
      name: safeName,
      originalName: String(downloaded.name || safeName),
      size: verifiedStat.size,
      type: extension.toLowerCase() === ".csv" ? "text/csv" : "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      storagePath,
      sha256,
      source: "salesforce-display-compliance-issue-tracking",
      retailerId: run.retailerId,
      retailerName: run.retailerName,
      extractionRunId: runId,
      extractionBatchId: run.displayComplianceBatchId,
      reportIdentity,
      reportStartDate: run.reportStartDate,
      reportEndDate: run.reportEndDate,
      displayComplianceSourceStartDate: run.displayComplianceSourceStartDate || null,
      displayComplianceSourceEndDate: run.displayComplianceSourceEndDate || null,
      displayComplianceFileGroup: "Issue Tracking",
      displayComplianceReportName: "Issue Tracking Report - Meridian",
      sharePoint: { provider: "sharepoint", status: "pending", folderPath: destination.folderPath },
      createdAt: FieldValue.serverTimestamp(),
      uploadedAt: FieldValue.serverTimestamp(),
      completedAt: FieldValue.serverTimestamp()
    });
    await runRef.set({ stage: "delivering", message: `Delivering ${safeName} to the Issue Tracking source folder.`, lastActivityAt: FieldValue.serverTimestamp() }, { merge: true });
    const uploaded = await uploadFileToSharePoint(downloaded.filePath, safeName, verifiedStat.size, destination);
    const sharePoint = { ...uploaded, uploadedAt: FieldValue.serverTimestamp() };
    await fileRef.set({ sharePoint }, { merge: true });
    await saveSalesforceSession(page, salesforceSessionKey || run.retailerId);
    const message = `${safeName} was verified and delivered to the Issue Tracking folder.`;
    await runRef.set({
      status: "completed",
      stage: "completed",
      fileId,
      fileName: safeName,
      fileSize: verifiedStat.size,
      fileSha256: sha256,
      storagePath,
      sharePoint,
      reportIdentity,
      message,
      completedAt: FieldValue.serverTimestamp(),
      lastActivityAt: FieldValue.serverTimestamp(),
      executionTimeline: FieldValue.arrayUnion(runTimelineEvent("completed", message, { fileId, fileName: safeName }))
    }, { merge: true });
    await updateReportDelivery(reportIdentity, { status: "completed", fileId, runId, fileName: safeName, storagePath });
  } catch (error) {
    console.error("Salesforce Display Compliance Issue Tracking run failed", runId, error);
    if (isSalesforceRetailer(run.retailerId) && salesforceSessionWasInvalidated(error)) {
      await clearSalesforceSession(salesforceSessionKey || run.retailerId);
      await appendRunTimeline(runRef, "salesforce-session-cleared", "Salesforce invalidated the stored session. A fresh MFA approval is required before restarting Issue Tracking.");
    }
    const cancelled = error instanceof ExtractionCancelledError || await extractionCancellationRequested(runRef);
    const message = cancelled
      ? "Issue Tracking extraction was aborted."
      : String(error.message || error).slice(0, 500);
    await runRef.set({
      status: cancelled ? "cancelled" : "failed",
      stage: "failed",
      message,
      reportIdentity,
      completedAt: FieldValue.serverTimestamp(),
      lastActivityAt: FieldValue.serverTimestamp(),
      executionTimeline: FieldValue.arrayUnion(runTimelineEvent("failed", message))
    }, { merge: true });
    await updateReportDelivery(reportIdentity, { status: "failed", runId, message });
  } finally {
    if (browser) await browser.close().catch(() => {});
    if (downloadDir) await fs.rm(downloadDir, { recursive: true, force: true }).catch(() => {});
    await releaseSalesforceBrowserLease(salesforceBrowserLease, runId);
    await advanceDisplayComplianceBatch(run.displayComplianceBatchId, runId).catch((error) => console.error("Could not advance Display Compliance batch after Issue Tracking", run.displayComplianceBatchId, error));
  }
}

async function remediateDisplayComplianceFileName(event) {
  const runRef = event.data.ref;
  const run = event.data.data();
  const runId = event.params.runId;
  const fileId = optionalText(run.fileId, 160);
  if (!fileId) throw new Error("The File 1 filename remediation run has no file ID.");
  const fileRef = db.collection("files").doc(fileId);
  const fileDoc = await fileRef.get();
  if (!fileDoc.exists) throw new Error("The File 1 filename remediation file record was not found.");
  const file = { id: fileDoc.id, ...fileDoc.data() };
  if (file.retailerId !== salesforceDisplayComplianceRetailerId || file.displayComplianceFileGroup !== "File 1") {
    throw new Error("Only Salesforce Display Compliance File 1 reports can be remediated.");
  }
  const priority = {
    customer: file.displayComplianceCustomer,
    activityType: file.displayComplianceActivityType,
    siebelId: file.displayComplianceSiebelId,
    priority: file.displayCompliancePriority
  };
  const expectedName = displayComplianceFileName({
    ...run,
    displayComplianceExportedAt: file.createdAt || run.displayComplianceExportedAt || null,
    reportStartDate: file.reportStartDate || run.reportStartDate,
    reportEndDate: file.reportEndDate || run.reportEndDate,
    displayComplianceCustomer: priority.customer,
    displayComplianceActivityType: priority.activityType
  }, file.originalName || file.name, priority);
  const destination = salesforceDisplayComplianceDestination({
    ...run,
    displayComplianceCustomer: priority.customer,
    displayComplianceFileGroup: "File 1"
  });
  if (file.sharePoint?.status === "uploaded" && file.sharePoint?.name === expectedName && file.sharePoint?.folderPath === destination.folderPath) {
    await runRef.set({
      status: "completed",
      fileId,
      fileName: expectedName,
      sharePoint: file.sharePoint,
      message: `${expectedName} already uses the safe File 1 name.`,
      completedAt: FieldValue.serverTimestamp()
    }, { merge: true });
    return;
  }
  await runRef.set({ status: "running", message: `Replacing the long SharePoint filename with ${expectedName}.` }, { merge: true });
  const previousSharePoint = file.sharePoint || null;
  const uploaded = await redeliverStoredFileToSharePoint(file, destination, expectedName);
  await fileRef.set({
    name: expectedName,
    sharePoint: { ...uploaded, uploadedAt: FieldValue.serverTimestamp() },
    filenameRemediatedAt: FieldValue.serverTimestamp()
  }, { merge: true });
  if (previousSharePoint?.itemId && previousSharePoint.itemId !== uploaded.itemId) {
    await removeSharePointItem(previousSharePoint).catch((error) => {
      console.warn("Could not remove the replaced long-name Display Compliance file", fileId, error.message || error);
    });
  }
  await runRef.set({
    status: "completed",
    fileId,
    fileName: expectedName,
    sharePoint: uploaded,
    message: `${expectedName} was delivered to SharePoint with a OneDrive-safe filename.`,
    completedAt: FieldValue.serverTimestamp(),
    executionTimeline: FieldValue.arrayUnion(runTimelineEvent("filename-remediated", "The long File 1 SharePoint filename was replaced with a OneDrive-safe filename.", { fileId, fileName: expectedName }))
  }, { merge: true });
}

async function processSalesforceDisplayComplianceBatchRun(event) {
  const runRef = event.data.ref;
  const run = event.data.data();
  const runId = event.params.runId;
  let browser;
  let page;
  let downloadDir;
  let salesforceSessionKey = "";
  let salesforceBrowserLease = null;
  let reportIdentity = "";
  let activeStep = { action: "salesforce-display-compliance" };
  let activeStepNumber = null;
  try {
    await ensureExtractionActive(runRef);
    const [retailer, extractionProfile, phaseTwoConfigDocument] = await Promise.all([
      loadRetailerAutomation(run.retailerId),
      run.extractionProfileId ? loadExtractionProfile(run.extractionProfileId) : Promise.resolve(null),
      db.collection("salesforceDisplayComplianceConfig").doc("current").get()
    ]);
    const phaseTwoConfig = phaseTwoConfigDocument.exists ? phaseTwoConfigDocument.data() : {};
    const steps = extractionProfile?.steps || retailer.steps;
    if (!Array.isArray(steps) || !steps.length) throw new Error("Display Compliance has no linked Salesforce workflow steps.");
    salesforceSessionKey = salesforceSessionKeyForRetailer(run.retailerId, retailer);
    salesforceBrowserLease = await acquireSalesforceBrowserLease(salesforceSessionKey || run.retailerId, runId, runRef, run.retailerName);
    await runRef.set({
      status: "running",
      message: run.workflowMode.endsWith("discover") ? "Restoring Salesforce to discover Display Compliance customers." : `Restoring Salesforce for ${run.displayComplianceCustomer}: ${run.displayComplianceActivityType} File 1.`,
      startedAt: FieldValue.serverTimestamp(),
      lastActivityAt: FieldValue.serverTimestamp(),
      executionTimeline: FieldValue.arrayUnion(runTimelineEvent("started", "Started Salesforce Display Compliance File 1 work."))
    }, { merge: true });
    downloadDir = await fs.mkdtemp(path.join(os.tmpdir(), "nexus-display-compliance-"));
    const launched = await launchAutomationBrowser(downloadDir);
    browser = launched.browser;
    page = launched.page;
    const restored = await restoreSalesforceSession(page, salesforceSessionKey || run.retailerId);
    if (restored) {
      retailer.salesforceSessionOrigin = typeof restored === "string" ? restored : "";
      await appendRunTimeline(runRef, "salesforce-session-restored", "A recent encrypted Salesforce session was restored before the File 1 run.");
    }
    await openSalesforceDisplayComplianceWorkspace({ page, retailer, steps, run, runRef, runId, downloadDir });
    activeStep = { action: "salesforce-display-compliance" };
    if (run.workflowMode === "salesforce-display-compliance-file1-discover") {
      const discoveredCustomers = await discoverSalesforceDisplayComplianceCustomers(page);
      const allowedChannels = displayComplianceChannels(run.displayComplianceAllowedChannels);
      const customers = allowedChannels.length
        ? discoveredCustomers.filter((customer) => allowedChannels.some((channel) => displayComplianceChannelMatches(channel, customer)))
        : discoveredCustomers;
      const excludedCustomers = discoveredCustomers.filter((customer) => !customers.includes(customer));
      const unavailableChannels = allowedChannels.filter((channel) => !discoveredCustomers.some((customer) => displayComplianceChannelMatches(channel, customer)));
      await saveSalesforceSession(page, salesforceSessionKey || run.retailerId);
      await runRef.set({
        status: "completed",
        displayComplianceCustomers: customers,
        displayComplianceCustomerCount: customers.length,
        displayComplianceDiscoveredCustomerCount: discoveredCustomers.length,
        displayComplianceExcludedCustomers: excludedCustomers,
        displayComplianceAllowedChannels: allowedChannels,
        displayComplianceUnavailableChannels: unavailableChannels,
        message: allowedChannels.length
          ? `${customers.length} of ${discoveredCustomers.length} Salesforce customers matched the configured File 1 channel scope.${unavailableChannels.length ? ` ${unavailableChannels.join(", ")} was not available in Salesforce.` : ""}`
          : `${customers.length} Salesforce customers were discovered for the File 1 batch.`,
        completedAt: FieldValue.serverTimestamp(),
        executionTimeline: FieldValue.arrayUnion(runTimelineEvent(
          "customers-discovered",
          allowedChannels.length
            ? `${customers.length} of ${discoveredCustomers.length} Display Compliance customers matched the stored channel scope.${unavailableChannels.length ? ` ${unavailableChannels.join(", ")} was unavailable.` : ""}`
            : `${customers.length} Display Compliance customers discovered.`
        ))
      }, { merge: true });
      return;
    }
    await runRef.set({ message: `Filtering Salesforce for ${run.displayComplianceCustomer}: ${run.displayComplianceActivityType}.` }, { merge: true });
    await salesforceConfigureDisplayCompliance(page, run, "");
    await salesforceGoToDisplayCompliancePage(page, Number(run.displayCompliancePage || 0));
    const priorityPage = await salesforceDisplayCompliancePriorityPage(page);
    const priorityIndex = Number(run.displayCompliancePriorityIndex || 0);
    const priority = priorityPage.rows[priorityIndex];
    await runRef.set({
      displayCompliancePageRows: priorityPage.rows.length,
      displayCompliancePageStart: priorityPage.pageStart,
      displayCompliancePageEnd: priorityPage.pageEnd,
      displayComplianceTotalRecords: priorityPage.totalRecords,
      lastActivityAt: FieldValue.serverTimestamp()
    }, { merge: true });
    if (!priority) {
      await saveSalesforceSession(page, salesforceSessionKey || run.retailerId);
      await runRef.set({
        status: "completed",
        noData: true,
        message: priorityPage.totalRecords ? "The expected File 1 priority was no longer present in Salesforce." : `No ${run.displayComplianceActivityType} priorities were returned for ${run.displayComplianceCustomer}.`,
        completedAt: FieldValue.serverTimestamp(),
        executionTimeline: FieldValue.arrayUnion(runTimelineEvent("no-priorities", "The current Salesforce customer/activity filter returned no File 1 priorities."))
      }, { merge: true });
      return;
    }
    const selectedPriority = {
      ...priority,
      customer: optionalText(priority.customer, 160) || run.displayComplianceCustomer,
      activityType: optionalText(priority.activityType, 40) || run.displayComplianceActivityType
    };
    reportIdentity = displayComplianceReportIdentity(run, selectedPriority);
    await runRef.set({
      reportIdentity,
      displayComplianceCustomer: selectedPriority.customer,
      displayComplianceActivityType: selectedPriority.activityType,
      displayCompliancePriority: selectedPriority.priority || null,
      displayComplianceSiebelId: selectedPriority.siebelId || null,
      displayCompliancePriorityStartDate: selectedPriority.priorityStartDate || null,
      displayCompliancePriorityEndDate: selectedPriority.priorityEndDate || null,
      message: `Preparing File 1 for ${selectedPriority.priority || selectedPriority.siebelId || "the selected priority"}.`
    }, { merge: true });
    const destination = salesforceDisplayComplianceDestination({ ...run, displayComplianceCustomer: selectedPriority.customer, displayComplianceFileGroup: "File 1" });
    const reservation = await reserveReportDelivery(runRef, runId, { ...run, displayComplianceFileGroup: "File 1" }, reportIdentity);
    if (reservation.state === "completed") {
      await completeExistingDisplayComplianceDelivery({ runRef, run, runId, reservation, destination });
      return;
    }
    if (reservation.state === "in-progress") throw new Error("An identical Display Compliance priority is already being extracted by another run.");
    activeStep = { action: "salesforceOpenDisplayCompliancePriority" };
    activeStepNumber = Number(run.currentStep || 0) + 1;
    await runRef.set({ message: `Opening ${selectedPriority.priority || selectedPriority.siebelId || "the selected priority"} in Salesforce.` }, { merge: true });
    await salesforceOpenDisplayCompliancePriority(page, priorityIndex);
    activeStep = { action: "salesforceDownloadDisplayCompliancePriority" };
    await runRef.set({ message: `Downloading File 1 for ${selectedPriority.priority || selectedPriority.siebelId || "the selected priority"}.` }, { merge: true });
    const downloaded = await salesforceDownloadDisplayCompliancePriority(page, downloadDir);
    const verifiedStat = await verifyDisplayComplianceDownload(downloaded);
    const sha256 = await hashFile(downloaded.filePath);
    const originalName = downloaded.name.replace(/[\\/#?%*:|"<>]/g, "_").slice(0, 240);
    const safeName = displayComplianceFileName(run, originalName, selectedPriority);
    const fileId = crypto.randomUUID();
    const storagePath = `uploads/${fileId}/${safeName}`;
    const bucket = getStorage().bucket();
    const [storedFile] = await bucket.upload(downloaded.filePath, {
      destination: storagePath,
      metadata: {
        contentType: "application/vnd.ms-excel",
        metadata: { extractionRunId: runId, retailerId: run.retailerId, reportIdentity, sha256 }
      }
    });
    const [storedMetadata] = await storedFile.getMetadata();
    if (Number(storedMetadata.size) !== verifiedStat.size) {
      await storedFile.delete().catch(() => {});
      throw new Error("The Display Compliance Firebase Storage upload failed size verification.");
    }
    const fileRef = db.collection("files").doc(fileId);
    let sharePoint = null;
    let workspaceCopies = [];
    try {
      await fileRef.set({
        name: safeName,
        originalName,
        size: verifiedStat.size,
        type: "application/vnd.ms-excel",
        storagePath,
        sha256,
        source: "salesforce-display-compliance-file1",
        retailerId: run.retailerId,
        retailerName: run.retailerName,
        extractionRunId: runId,
        extractionBatchId: run.displayComplianceBatchId,
        reportIdentity,
        reportStartDate: reportDatesForRun(run).startDate,
        reportEndDate: reportDatesForRun(run).endDate,
        displayComplianceFileGroup: "File 1",
        displayComplianceCustomer: selectedPriority.customer,
        displayComplianceActivityType: selectedPriority.activityType,
        displayCompliancePriority: selectedPriority.priority || null,
        displayComplianceSiebelId: selectedPriority.siebelId || null,
        displayCompliancePriorityStartDate: selectedPriority.priorityStartDate || null,
        displayCompliancePriorityEndDate: selectedPriority.priorityEndDate || null,
        sharePoint: { provider: "sharepoint", status: "pending", folderPath: destination.folderPath },
        createdAt: FieldValue.serverTimestamp(),
        uploadedAt: FieldValue.serverTimestamp(),
        completedAt: FieldValue.serverTimestamp()
      });
      await runRef.set({ message: `Delivering ${safeName} to SharePoint.` }, { merge: true });
      const uploaded = await uploadFileToSharePoint(downloaded.filePath, safeName, verifiedStat.size, destination);
      sharePoint = { ...uploaded, uploadedAt: FieldValue.serverTimestamp() };
      workspaceCopies = await deliverDisplayComplianceWorkspaceCopies({
        filePath: downloaded.filePath,
        fileName: safeName,
        fileSize: verifiedStat.size,
        config: phaseTwoConfig,
        customer: selectedPriority.customer,
        fileGroup: "File 1"
      });
      await fileRef.set({ sharePoint, workspaceCopies }, { merge: true });
    } catch (error) {
      await fileRef.set({ sharePoint: { provider: "sharepoint", status: "failed", message: String(error.message || error).slice(0, 500), folderPath: destination.folderPath, failedAt: FieldValue.serverTimestamp() } }, { merge: true }).catch(() => {});
      throw error;
    }
    await saveSalesforceSession(page, salesforceSessionKey || run.retailerId);
    await runRef.set({
      status: "completed",
      isDuplicate: false,
      fileId,
      fileName: safeName,
      originalFileName: originalName,
      fileSize: verifiedStat.size,
      fileSha256: sha256,
      storagePath,
      sharePoint,
      workspaceCopies,
      reportIdentity,
      message: `${safeName} was saved and delivered to SharePoint File 1${workspaceCopies.length ? `, with ${workspaceCopies.filter((copy) => copy.status === "uploaded").length}/${workspaceCopies.length} customer workspace ${workspaceCopies.length === 1 ? "copy" : "copies"} delivered` : ""}.`,
      completedAt: FieldValue.serverTimestamp(),
      executionTimeline: FieldValue.arrayUnion(runTimelineEvent("completed", `${safeName} was verified and delivered to SharePoint File 1.`, { fileId, fileName: safeName }))
    }, { merge: true });
    await updateReportDelivery(reportIdentity, { status: "completed", fileId, runId, fileName: safeName, storagePath });
  } catch (error) {
    console.error("Salesforce Display Compliance File 1 batch run failed", runId, error);
    if (isSalesforceRetailer(run.retailerId) && salesforceSessionWasInvalidated(error)) {
      await clearSalesforceSession(salesforceSessionKey || run.retailerId);
      await appendRunTimeline(runRef, "salesforce-session-cleared", "Salesforce invalidated the stored session. A fresh MFA approval is required before restarting this batch.");
    }
    if (error instanceof ExtractionCancelledError || await extractionCancellationRequested(runRef)) {
      await runRef.set({
        status: "cancelled",
        message: "Display Compliance File 1 extraction was aborted.",
        reportIdentity: reportIdentity || null,
        completedAt: FieldValue.serverTimestamp(),
        executionTimeline: FieldValue.arrayUnion(runTimelineEvent("aborted", "The File 1 extraction was stopped by an administrator."))
      }, { merge: true });
    } else if (isDisplayComplianceEmptyPlaceholder(error)) {
      const message = "Salesforce returned an empty File 1 export placeholder for this priority. Nexus marked only this priority as no-data and will continue the Display Compliance batch.";
      await runRef.set({
        status: "completed_no_data",
        noData: true,
        message,
        reportIdentity: reportIdentity || null,
        completedAt: FieldValue.serverTimestamp(),
        executionTimeline: FieldValue.arrayUnion(runTimelineEvent("completed-no-data", message))
      }, { merge: true });
      if (reportIdentity) await updateReportDelivery(reportIdentity, { status: "completed_no_data", runId, message });
    } else {
      await captureFailureEvidence({ page, runRef, runId, step: activeStep, stepNumber: activeStepNumber }).catch(() => {});
      await runRef.set({
        status: "failed",
        message: String(error.message || error).slice(0, 500),
        reportIdentity: reportIdentity || null,
        completedAt: FieldValue.serverTimestamp(),
        executionTimeline: FieldValue.arrayUnion(runTimelineEvent("failed", String(error.message || error).slice(0, 500)))
      }, { merge: true });
      await updateReportDelivery(reportIdentity, { status: "failed", runId, message: String(error.message || error).slice(0, 500) });
    }
  } finally {
    if (browser) await browser.close().catch(() => {});
    if (downloadDir) await fs.rm(downloadDir, { recursive: true, force: true }).catch(() => {});
    await releaseSalesforceBrowserLease(salesforceBrowserLease, runId);
    await advanceDisplayComplianceBatch(run.displayComplianceBatchId, runId).catch((error) => console.error("Could not advance Display Compliance batch", run.displayComplianceBatchId, error));
  }
}

async function processSalesforceSessionWarmup(event) {
  const runRef = event.data.ref;
  const run = event.data.data();
  const runId = event.params.runId;
  let browser;
  let page;
  let salesforceSessionKey = "";
  let salesforceBrowserLease = null;
  try {
    await ensureExtractionActive(runRef);
    const [retailer, extractionProfile] = await Promise.all([
      loadRetailerAutomation(run.retailerId),
      run.extractionProfileId ? loadExtractionProfile(run.extractionProfileId) : Promise.resolve(null)
    ]);
    const steps = extractionProfile?.steps || retailer.steps;
    const otpStepIndex = Array.isArray(steps) ? steps.findIndex((step) => step.action === "fillOtp") : -1;
    if (otpStepIndex < 0) throw new Error("The Salesforce workflow does not contain an authentication step.");

    salesforceSessionKey = salesforceSessionKeyForRetailer(run.retailerId, retailer);
    salesforceBrowserLease = await acquireSalesforceBrowserLease(salesforceSessionKey || run.retailerId, runId, runRef, run.retailerName);
    await runRef.set({
      status: "running",
      totalSteps: otpStepIndex + 1,
      message: "Preparing a secure Salesforce sign-in. No report will be downloaded.",
      startedAt: FieldValue.serverTimestamp(),
      lastActivityAt: FieldValue.serverTimestamp(),
      executionTimeline: FieldValue.arrayUnion(runTimelineEvent("started", "Started Salesforce session refresh."))
    }, { merge: true });

    const launched = await launchAutomationBrowser();
    browser = launched.browser;
    page = launched.page;
    const restored = await restoreSalesforceSession(page, salesforceSessionKey || run.retailerId);
    if (restored) {
      retailer.salesforceSessionOrigin = typeof restored === "string" ? restored : "";
      await appendRunTimeline(runRef, "salesforce-session-restored", "A recent encrypted Salesforce session was restored for verification.");
    }

    for (let index = 0; index <= otpStepIndex; index += 1) {
      await ensureExtractionActive(runRef);
      const step = steps[index];
      await runRef.set({
        status: "running",
        currentStep: index + 1,
        totalSteps: otpStepIndex + 1,
        currentStepAction: step.action,
        message: `Refreshing Salesforce session: step ${index + 1} of ${otpStepIndex + 1} (${step.action}).`,
        lastActivityAt: FieldValue.serverTimestamp(),
        executionTimeline: FieldValue.arrayUnion(runTimelineEvent("step-started", `Step ${index + 1}: ${step.action}`, { step: index + 1, action: step.action }))
      }, { merge: true });
      await runStep(page, step, retailer, "", run, { runRef, runId, stepNumber: index + 1 });
      await appendRunTimeline(runRef, "step-completed", `Step ${index + 1}: ${step.action} completed.`, { step: index + 1, action: step.action });
    }

    if (!(await saveSalesforceSession(page, salesforceSessionKey || run.retailerId))) {
      throw new Error("Salesforce did not confirm the sign-in, so no session was saved.");
    }
    const expiresAt = new Date(Date.now() + salesforceSessionMaxAgeMs).toISOString();
    await runRef.set({
      status: "completed",
      message: "Salesforce sign-in was confirmed and the encrypted session is saved for up to 24 hours. No report was downloaded.",
      sessionExpiresAt: expiresAt,
      completedAt: FieldValue.serverTimestamp(),
      executionTimeline: FieldValue.arrayUnion(runTimelineEvent("salesforce-session-saved", "Salesforce sign-in was verified and the encrypted 24-hour session was saved."))
    }, { merge: true });
  } catch (error) {
    console.error("Salesforce session refresh failed", runId, error);
    if (isSalesforceRetailer(run.retailerId) && salesforceSessionWasInvalidated(error)) {
      await clearSalesforceSession(salesforceSessionKey || run.retailerId);
    }
    if (error instanceof ExtractionCancelledError || await extractionCancellationRequested(runRef)) {
      await runRef.set({
        status: "cancelled",
        message: "Salesforce session refresh was aborted.",
        completedAt: FieldValue.serverTimestamp()
      }, { merge: true });
    } else {
      await runRef.set({
        status: "failed",
        message: String(error.message || error).slice(0, 800),
        completedAt: FieldValue.serverTimestamp(),
        executionTimeline: FieldValue.arrayUnion(runTimelineEvent("failed", String(error.message || error).slice(0, 500)))
      }, { merge: true });
    }
  } finally {
    await page?.close().catch(() => {});
    await browser?.close().catch(() => {});
    await releaseSalesforceBrowserLease(salesforceBrowserLease, runId);
  }
}




function salesDashboardNormalise(value) {
  return String(value || "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
}

function salesDashboardHeaderIndex(headers, aliases) {
  const wanted = aliases.map(salesDashboardNormalise);
  return headers.findIndex((header) => wanted.includes(salesDashboardNormalise(header)));
}

function salesDashboardSheetHeaders(sheet, matcher) {
  let best = null;
  for (let rowNumber = 1; rowNumber <= Math.min(sheet.rowCount, 30); rowNumber += 1) {
    const values = (sheet.getRow(rowNumber).values || []).slice(1).map((value) => String(value || "").trim());
    const candidate = matcher(values);
    if (candidate && (!best || candidate.score > best.score)) best = { ...candidate, rowNumber, headers: values };
  }
  return best;
}

function salesDashboardValue(values, index) {
  return index >= 0 ? values[index] : null;
}

function salesDashboardNumber(value) {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  const source = String(value ?? "").trim();
  if (!source) return 0;
  const normalised = source.replace(/[R$\s,]/g, "").replace(/^\((.*)\)$/, "-$1");
  const parsed = Number(normalised);
  return Number.isFinite(parsed) ? parsed : 0;
}

function salesDashboardDate(value, fallback) {
  if (value instanceof Date && !Number.isNaN(value.getTime())) return value.toISOString().slice(0, 10);
  const source = String(value || "").trim();
  if (!source) return fallback;
  const southAfrican = source.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})/);
  if (southAfrican) return `${southAfrican[3]}-${southAfrican[2].padStart(2, "0")}-${southAfrican[1].padStart(2, "0")}`;
  const parsed = new Date(source);
  return Number.isNaN(parsed.getTime()) ? fallback : parsed.toISOString().slice(0, 10);
}

function salesDashboardCleanText(value, max = 240) {
  return String(value ?? "").replace(/\s+/g, " ").trim().slice(0, max);
}

async function downloadSalesDashboardWorkbook(storagePath, directory, filename) {
  const destination = path.join(directory, filename.replace(/[^a-z0-9._-]/gi, "_") || "source.xlsx");
  await getStorage().bucket().file(storagePath).download({ destination });
  return destination;
}

async function readGeoRepSalesStoreMaster(master, directory) {
  const sourcePath = await downloadSalesDashboardWorkbook(master.storagePath, directory, master.sourceName || "geo-rep-orders-store-master.xlsx");
  const workbook = new ExcelJS.Workbook();
  await workbook.xlsx.readFile(sourcePath);
  let selected = null;
  workbook.worksheets.forEach((sheet) => {
    const candidate = salesDashboardSheetHeaders(sheet, (headers) => {
      const storeName = salesDashboardHeaderIndex(headers, ["Store Name", "Meridian Store Name", "Customer Name", "Customer"]);
      const storeCode = salesDashboardHeaderIndex(headers, ["Geo Rep Store Code", "Diplomat Customer no", "Store Code", "Customer Code", "Diplomat Store Code", "Meridian Store Code"]);
      const region = salesDashboardHeaderIndex(headers, ["Region", "Region Name"]);
      if (region < 0 || (storeName < 0 && storeCode < 0)) return null;
      return { score: 30 + (storeName >= 0 ? 10 : 0) + (storeCode >= 0 ? 10 : 0), storeName, storeCode, region,
        rep: salesDashboardHeaderIndex(headers, ["Rep", "Sales Rep", "Representative", "Merchandiser"]),
        client: salesDashboardHeaderIndex(headers, ["Client", "Client Name", "Customer Group"]),
        banner: salesDashboardHeaderIndex(headers, ["Banner", "Banner Name", "Retail Banner"]),
        channel: salesDashboardHeaderIndex(headers, ["Channel", "Channel Name", "Retail Channel"]),
        division: salesDashboardHeaderIndex(headers, ["Division", "Business Division"]) };
    });
    if (candidate && (!selected || candidate.score > selected.score)) selected = { sheet, ...candidate };
  });
  if (!selected) throw new Error("The Geo Rep Capture Orders Store Master needs a Region column and either Store Name or Store Code.");
  const entries = new Map();
  let sourceRows = 0;
  let excludedRows = 0;
  const duplicateKeys = new Set();
  selected.sheet.eachRow((row, rowNumber) => {
    if (rowNumber <= selected.rowNumber) return;
    sourceRows += 1;
    const values = (row.values || []).slice(1);
    const storeName = salesDashboardCleanText(salesDashboardValue(values, selected.storeName));
    const storeCode = salesDashboardCleanText(salesDashboardValue(values, selected.storeCode), 120);
    const region = salesDashboardCleanText(salesDashboardValue(values, selected.region), 120);
    const rep = salesDashboardCleanText(salesDashboardValue(values, selected.rep), 160);
    const client = salesDashboardCleanText(salesDashboardValue(values, selected.client), 120);
    const banner = salesDashboardCleanText(salesDashboardValue(values, selected.banner), 120);
    const channel = salesDashboardCleanText(salesDashboardValue(values, selected.channel), 120);
    const division = salesDashboardCleanText(salesDashboardValue(values, selected.division), 120);
    if (!region || (!storeName && !storeCode)) {
      excludedRows += 1;
      return;
    }
    const entry = { storeName, storeCode, region, rep, client, banner, channel, division };
    if (storeCode) {
      const key = `code:${salesDashboardNormalise(storeCode)}`;
      if (entries.has(key)) duplicateKeys.add(key);
      entries.set(key, entry);
    }
    if (storeName) {
      const key = `name:${salesDashboardNormalise(storeName)}`;
      if (entries.has(key)) duplicateKeys.add(key);
      entries.set(key, entry);
    }
  });
  const uniqueEntries = [...new Map([...entries.values()].map((entry) => [`${entry.storeCode}|${entry.storeName}|${entry.region}`, entry])).values()];
  if (!uniqueEntries.length) throw new Error("The Geo Rep Capture Orders Store Master has no usable store and region rows.");
  return {
    entries: uniqueEntries,
    sheetName: selected.sheet.name,
    sourceRows,
    excludedRows,
    duplicateKeyCount: duplicateKeys.size
  };
}

async function readGeoRepSalesTransactions(file, directory, fallbackDate) {
  const sourcePath = await downloadSalesDashboardWorkbook(file.storagePath, directory, file.name || "geo-rep-transactions.xlsx");
  const workbook = new ExcelJS.Workbook();
  await workbook.xlsx.readFile(sourcePath);
  const sheet = workbook.worksheets.find((item) => salesDashboardNormalise(item.name) === "order details");
  if (!sheet) throw new Error("The downloaded Geo Rep Capture Transaction Report does not contain the required Order Details tab.");
  const selected = salesDashboardSheetHeaders(sheet, (headers) => {
    const storeName = salesDashboardHeaderIndex(headers, ["Customer Name", "Store Name", "Customer"]);
    const storeCode = salesDashboardHeaderIndex(headers, ["Diplomat Customer no", "Diplomat Store Code", "Store Code", "Customer Code"]);
    const sku = salesDashboardHeaderIndex(headers, ["Product SKU Code", "SKU", "Product SKU", "Item Code", "Stock Code"]);
    const product = salesDashboardHeaderIndex(headers, ["Product Name", "Product", "Item Description", "SKU Description"]);
    const quantity = salesDashboardHeaderIndex(headers, ["Quantity", "Qty", "Order Quantity", "Units"]);
    const value = salesDashboardHeaderIndex(headers, ["Total", "Total Value", "Order Value", "Sales Value", "Line Total", "Amount", "Value"]);
    const orderNumber = salesDashboardHeaderIndex(headers, ["Transaction Number", "Order Number", "Order No", "Order ID", "Transaction ID", "Document Number"]);
    if ((storeName < 0 && storeCode < 0) || (sku < 0 && product < 0) || (quantity < 0 && value < 0) || orderNumber < 0) return null;
    return {
      score: 100, storeName, storeCode, sku, product, quantity, value, orderNumber,
      barcode: salesDashboardHeaderIndex(headers, ["Barcode", "EAN", "UPC"]),
      unitPrice: salesDashboardHeaderIndex(headers, ["Price", "Unit Price", "Selling Price", "Sub-total"]),
      orderDate: salesDashboardHeaderIndex(headers, ["Date", "Order Date", "Transaction Date", "Created Date"]),
      rep: salesDashboardHeaderIndex(headers, ["User", "Rep", "Sales Rep", "Representative", "Created By"]),
      orderedBy: salesDashboardHeaderIndex(headers, ["Ordered by", "Order placed by"]),
      manager: salesDashboardHeaderIndex(headers, ["Manager", "Line Manager"]),
      status: salesDashboardHeaderIndex(headers, ["Status"]),
      poNumber: salesDashboardHeaderIndex(headers, ["PO Number", "Purchase Order"]),
      client: salesDashboardHeaderIndex(headers, ["Client", "Client Name", "Customer Group"]),
      brand: salesDashboardHeaderIndex(headers, ["Brand", "Brand Name"]),
      category: salesDashboardHeaderIndex(headers, ["Category", "Category Name", "Product Category"]),
      channel: salesDashboardHeaderIndex(headers, ["Channel", "Channel Name", "Retail Channel"]),
      division: salesDashboardHeaderIndex(headers, ["Division", "Business Division"])
    };
  });
  if (!selected) throw new Error("The Order Details tab is missing one or more required fields: Customer Name or Diplomat Customer no, Product SKU Code or Product Name, Quantity or Total, and Transaction Number.");
  const rows = [];
  sheet.eachRow((row, rowNumber) => {
    if (rowNumber <= selected.rowNumber) return;
    const values = (row.values || []).slice(1);
    const storeName = salesDashboardCleanText(salesDashboardValue(values, selected.storeName));
    const storeCode = salesDashboardCleanText(salesDashboardValue(values, selected.storeCode), 120);
    const sku = salesDashboardCleanText(salesDashboardValue(values, selected.sku), 160);
    const product = salesDashboardCleanText(salesDashboardValue(values, selected.product), 240);
    const quantity = salesDashboardNumber(salesDashboardValue(values, selected.quantity));
    const unitPrice = salesDashboardNumber(salesDashboardValue(values, selected.unitPrice));
    const valueCell = salesDashboardNumber(salesDashboardValue(values, selected.value));
    const value = valueCell || (quantity * unitPrice);
    if ((!storeName && !storeCode) || (!sku && !product) || (!quantity && !value)) return;
    rows.push({
      orderNumber: salesDashboardCleanText(salesDashboardValue(values, selected.orderNumber), 160),
      orderDate: salesDashboardDate(salesDashboardValue(values, selected.orderDate), fallbackDate),
      storeName, storeCode, sku, product, quantity, unitPrice: unitPrice || (quantity ? value / quantity : 0), value,
      barcode: salesDashboardCleanText(salesDashboardValue(values, selected.barcode), 160),
      rep: salesDashboardCleanText(salesDashboardValue(values, selected.rep), 160),
      orderedBy: salesDashboardCleanText(salesDashboardValue(values, selected.orderedBy), 160),
      manager: salesDashboardCleanText(salesDashboardValue(values, selected.manager), 160),
      status: salesDashboardCleanText(salesDashboardValue(values, selected.status), 80),
      poNumber: salesDashboardCleanText(salesDashboardValue(values, selected.poNumber), 160),
      client: salesDashboardCleanText(salesDashboardValue(values, selected.client), 120),
      brand: salesDashboardCleanText(salesDashboardValue(values, selected.brand), 120),
      category: salesDashboardCleanText(salesDashboardValue(values, selected.category), 120),
      channel: salesDashboardCleanText(salesDashboardValue(values, selected.channel), 120),
      division: salesDashboardCleanText(salesDashboardValue(values, selected.division), 120)
    });
  });
  if (!rows.length) throw new Error("The Geo Rep Capture Orders detail tab contains no transaction rows for the requested month.");
  return { rows, sheetName: sheet.name };
}

async function remapGeoRepSalesTransactionsFromMaster(masterData, periodKey) {
  const byCode = new Map();
  const byName = new Map();
  masterData.entries.forEach((entry) => {
    if (entry.storeCode) byCode.set(salesDashboardNormalise(entry.storeCode), entry);
    if (entry.storeName) byName.set(salesDashboardNormalise(entry.storeName), entry);
  });
  const snapshot = await db.collection("salesTransactions").where("periodKey", "==", periodKey).limit(30000).get();
  if (snapshot.empty) return { periodKey, reviewedRows: 0, mappedRows: 0, unmappedRows: 0, missingRepRows: 0 };
  const writer = db.bulkWriter();
  let mappedRows = 0;
  let missingRepRows = 0;
  snapshot.docs.forEach((document) => {
    const row = document.data() || {};
    const codeMatch = row.storeCode && byCode.get(salesDashboardNormalise(row.storeCode));
    const nameMatch = !codeMatch && row.storeName && byName.get(salesDashboardNormalise(row.storeName));
    const matched = codeMatch || nameMatch || null;
    const sourceRep = salesDashboardCleanText(row.sourceRep || row.rep, 160);
    const mappedRep = salesDashboardCleanText(matched?.rep, 160);
    const rep = sourceRep || mappedRep || "Unassigned";
    const repMissing = !sourceRep && !mappedRep;
    if (matched) mappedRows += 1;
    if (repMissing) missingRepRows += 1;
    writer.set(document.ref, {
      region: salesDashboardCleanText(matched?.region, 120) || "Unmapped",
      mapped: Boolean(matched), mappingMethod: codeMatch ? "store-code" : nameMatch ? "store-name" : "unmapped",
      sourceRep, mappedRep, rep, repMissing,
      storeMasterRemappedAt: FieldValue.serverTimestamp()
    }, { merge: true });
  });
  await writer.close();
  return { periodKey, reviewedRows: snapshot.size, mappedRows, unmappedRows: snapshot.size - mappedRows, missingRepRows };
}

function geoRepSalesApiText(source, aliases, max = 240) {
  if (!source || typeof source !== "object") return "";
  const wanted = new Set(aliases.map(salesDashboardNormalise));
  const direct = Object.entries(source).find(([key]) => wanted.has(salesDashboardNormalise(key)));
  if (direct) return salesDashboardCleanText(direct[1], max);
  for (const value of Object.values(source)) {
    if (value && typeof value === "object" && !Array.isArray(value)) {
      const nested = geoRepSalesApiText(value, aliases, max);
      if (nested) return nested;
    }
  }
  return "";
}

function geoRepSalesApiNumber(source, aliases) {
  const value = geoRepSalesApiText(source, aliases, 80);
  return salesDashboardNumber(value);
}

function geoRepSalesApiDate(source, fallback) {
  return salesDashboardDate(
    geoRepSalesApiText(source, [
      "completed_datetime_utc", "completed_date_timezone", "submission_date", "expected_delivery_date",
      "schedule_date", "added_date_utc", "timestamp_utc", "date", "order_date"
    ], 80),
    fallback
  );
}

function geoRepSalesApiPeriod(now = new Date()) {
  const current = localDateParts(now, "Africa/Johannesburg").date;
  const periodKey = current.slice(0, 7);
  return { periodKey, startDate: `${periodKey}-01`, endDate: current };
}

function geoRepSalesApiRangeParameters(period) {
  return {
    added_date_start: `${period.startDate}T00:00:00`,
    added_date_end: `${period.endDate}T23:59:59`
  };
}

async function geoRepSalesApiUserLookup() {
  const snapshot = await db.collection("geoRepApiUsers").limit(5000).get().catch(() => null);
  const users = new Map();
  if (!snapshot) return users;
  snapshot.docs.forEach((document) => {
    const row = document.data()?.data || {};
    const id = salesDashboardCleanText(row.user_id || row.id || row.userId, 120);
    const name = salesDashboardCleanText(row.user_name || row.name || [row.first_name, row.surname].filter(Boolean).join(" "), 160);
    if (id && name) users.set(id, name);
  });
  return users;
}

function geoRepSalesApiProductLines(epod, details) {
  const submissionLines = [];
  (Array.isArray(details.submissions) ? details.submissions : []).forEach((submission) => {
    (Array.isArray(submission.products) ? submission.products : []).forEach((product) => {
      submissionLines.push({ ...product, submissionId: submission.submission_id, submissionDate: submission.submission_date });
    });
  });
  const products = submissionLines.length ? submissionLines : (Array.isArray(details.products) ? details.products : Array.isArray(epod.products) ? epod.products : []);
  return products.length ? products : [{}];
}

function geoRepSalesApiRowsFromEpod(epod, details, users, fallbackDate) {
  const merged = { ...(epod || {}), ...(details || {}) };
  const orderNumber = geoRepSalesApiText(merged, ["epod_number", "transaction_number", "order_number", "order_no", "reference"], 160)
    || geoRepSalesApiText(merged, ["epod_id"], 160);
  const storeName = geoRepSalesApiText(merged, ["location_name", "customer_name", "store_name", "customer"], 240);
  const storeCode = geoRepSalesApiText(merged, ["location_id", "customer_code", "store_code", "diplomat_customer_no"], 120);
  const assignedUserId = geoRepSalesApiText(merged, ["assigned_user_id", "user_id"], 120);
  const sourceRep = geoRepSalesApiText(merged, ["assigned_user_name", "user_name", "rep", "representative"], 160) || users.get(assignedUserId) || "";
  const manager = geoRepSalesApiText(merged, ["manager", "line_manager"], 160);
  const status = geoRepSalesApiText(merged, ["status", "delivery_status"], 80) || "Unspecified";
  const orderedBy = geoRepSalesApiText(merged, ["ordered_by", "created_by"], 160);
  const poNumber = geoRepSalesApiText(merged, ["po_number", "purchase_order"], 160);
  const client = geoRepSalesApiText(merged, ["client", "client_name", "customer_group"], 120);
  const channel = geoRepSalesApiText(merged, ["channel", "channel_name", "retail_channel"], 120);
  const division = geoRepSalesApiText(merged, ["division", "business_division", "business_unit"], 120);
  return geoRepSalesApiProductLines(epod, details).map((product) => {
    const productName = geoRepSalesApiText(product, ["product_name", "product", "item_description", "sku_description"], 240);
    const sku = geoRepSalesApiText(product, ["sku_code", "product_sku_code", "sku", "item_code", "stock_code"], 160);
    const quantity = geoRepSalesApiNumber(product, ["qty", "quantity", "order_quantity", "units"]);
    const unitPrice = geoRepSalesApiNumber(product, ["unit_price", "price", "selling_price"]);
    const value = geoRepSalesApiNumber(product, ["total", "total_value", "line_total", "amount", "value"]) || quantity * unitPrice;
    return {
      orderNumber,
      orderDate: salesDashboardDate(product.submissionDate, geoRepSalesApiDate(merged, fallbackDate)),
      storeName,
      storeCode,
      sku,
      product: productName || sku || "Unspecified product",
      quantity,
      unitPrice: unitPrice || (quantity ? value / quantity : 0),
      value,
      barcode: geoRepSalesApiText(product, ["barcode", "ean", "upc"], 160),
      rep: sourceRep,
      orderedBy,
      manager,
      status,
      poNumber,
      client,
      channel,
      division,
      brand: geoRepSalesApiText(product, ["brand", "brand_name"], 120),
      category: geoRepSalesApiText(product, ["category", "category_name", "product_category"], 120),
      epodId: geoRepSalesApiText(merged, ["epod_id"], 120),
      sourceSystem: "geo-rep-open-api"
    };
  }).filter((row) => row.orderNumber && (row.storeName || row.storeCode) && (row.sku || row.product) && (row.quantity || row.value));
}

async function importGeoRepSalesTransactionsFromApi({ trigger = "scheduled", actor = null, now = new Date() } = {}) {
  const configDoc = await db.collection("salesDashboardConfig").doc("current").get();
  const config = configDoc.exists ? configDoc.data() || {} : {};
  if (!config.storeMasterId) throw new Error("Save the Geo Rep Capture Orders Store Master before running the API sales import.");
  const masterDoc = await db.collection("salesStoreMasters").doc(config.storeMasterId).get();
  if (!masterDoc.exists) throw new Error("The selected Geo Rep Capture Orders Store Master is no longer available.");
  const period = geoRepSalesApiPeriod(now);
  const importRef = db.collection("salesTransactionImports").doc(`geo-rep-open-api-${period.periodKey.replace(/-/g, "")}-${period.endDate.replace(/-/g, "")}`);
  await importRef.set({
    source: "geo-rep-open-api", status: "running", trigger, periodKey: period.periodKey,
    reportStartDate: period.startDate, reportEndDate: period.endDate,
    sourceFileId: `geo-rep-open-api-${period.periodKey}`, sourceFileName: "Geo Rep Open API EPOD Details",
    storeMasterId: config.storeMasterId, storeMasterName: config.storeMasterName || masterDoc.data().name || null,
    message: "Reading Geo Rep Open API EPOD order details for the sales dashboard.",
    actorUid: optionalText(actor?.uid, 160) || null, actorEmail: optionalText(actor?.email, 320) || null,
    createdAt: FieldValue.serverTimestamp(), updatedAt: FieldValue.serverTimestamp()
  }, { merge: true });
  const tempDirectory = await fs.mkdtemp(path.join(os.tmpdir(), "nexus-geo-api-orders-"));
  try {
    const credentials = await geoRepOpenApiCredentials();
    const [masterData, users, epodsResult] = await Promise.all([
      readGeoRepSalesStoreMaster(masterDoc.data(), tempDirectory),
      geoRepSalesApiUserLookup(),
      geoRepOpenApiFetchAllRecords("epods", geoRepSalesApiRangeParameters(period), credentials)
    ]);
    if (!epodsResult.records.length) {
      const summary = {
        periodKey: period.periodKey, reportStartDate: period.startDate, reportEndDate: period.endDate,
        sourceRows: 0, uniqueSourceRows: 0, duplicateSourceRows: 0, newRecords: 0, existingRecords: 0,
        periodOrderLines: 0, uniqueOrders: 0, mappedRows: 0, unmappedRows: 0, missingRegionRows: 0, missingRepRows: 0,
        source: "geo-rep-open-api", completedAt: FieldValue.serverTimestamp()
      };
      await Promise.all([
        importRef.set({ status: "no-data", message: "Geo Rep Open API returned no EPOD order records for the current month. Existing dashboard data was left unchanged.", ...summary, updatedAt: FieldValue.serverTimestamp() }, { merge: true }),
        db.collection("salesDashboardConfig").doc("current").set({ lastApiImport: summary, updatedAt: FieldValue.serverTimestamp() }, { merge: true })
      ]);
      return { status: "no-data", importId: importRef.id, ...summary };
    }
    const rows = [];
    for (let index = 0; index < epodsResult.records.length; index += 8) {
      const batch = epodsResult.records.slice(index, index + 8);
      const details = await Promise.all(batch.map((epod) => geoRepOpenApiGet(geoRepOpenApiEpodDetailsEndpoint, { epod_id: epod.epod_id }, credentials).catch((error) => ({ error, epod }))));
      details.forEach((detail, offset) => {
        if (detail.error) return;
        rows.push(...geoRepSalesApiRowsFromEpod(batch[offset], detail, users, period.endDate));
      });
      await importRef.set({ message: `Expanded ${Math.min(index + batch.length, epodsResult.records.length).toLocaleString("en-ZA")} of ${epodsResult.records.length.toLocaleString("en-ZA")} API order headers.`, updatedAt: FieldValue.serverTimestamp() }, { merge: true });
    }
    const byCode = new Map();
    const byName = new Map();
    masterData.entries.forEach((entry) => {
      if (entry.storeCode) byCode.set(salesDashboardNormalise(entry.storeCode), entry);
      if (entry.storeName) byName.set(salesDashboardNormalise(entry.storeName), entry);
    });
    const transactions = rows.map((row) => {
      const codeMatch = row.storeCode && byCode.get(salesDashboardNormalise(row.storeCode));
      const nameMatch = !codeMatch && row.storeName && byName.get(salesDashboardNormalise(row.storeName));
      const matched = codeMatch || nameMatch || null;
      const sourceRep = salesDashboardCleanText(row.rep, 160);
      const mappedRep = salesDashboardCleanText(matched?.rep, 160);
      return {
        ...row,
        region: salesDashboardCleanText(matched?.region, 120) || "Unmapped",
        client: salesDashboardCleanText(row.client || matched?.client, 120),
        banner: salesDashboardCleanText(matched?.banner, 120),
        channel: salesDashboardCleanText(row.channel || matched?.channel, 120),
        division: salesDashboardCleanText(row.division || matched?.division, 120),
        mapped: Boolean(matched),
        mappingMethod: codeMatch ? "store-code" : nameMatch ? "store-name" : "unmapped",
        sourceRep,
        mappedRep,
        rep: sourceRep || mappedRep || "Unassigned",
        repMissing: !sourceRep && !mappedRep
      };
    });
    const uniqueTransactions = new Map();
    transactions.forEach((row) => {
      const transactionKey = crypto.createHash("sha256").update([
        period.periodKey, row.orderNumber, row.barcode || row.sku || row.product,
        row.storeCode || row.storeName, row.orderDate, row.quantity, row.value
      ].map(salesDashboardNormalise).join("|")).digest("hex").slice(0, 40);
      if (!uniqueTransactions.has(transactionKey)) uniqueTransactions.set(transactionKey, { ...row, transactionKey });
    });
    const deduplicatedTransactions = [...uniqueTransactions.values()];
    const existing = await db.collection("salesTransactions").where("periodKey", "==", period.periodKey).get();
    const retainedExistingIds = new Set(existing.docs.map((document) => document.id));
    const newTransactions = deduplicatedTransactions.filter((row) => !retainedExistingIds.has(`${period.periodKey.replace(/-/g, "")}-${row.transactionKey}`));
    const incomingDocumentIds = new Set(deduplicatedTransactions.map((row) => `${period.periodKey.replace(/-/g, "")}-${row.transactionKey}`));
    const staleApiRows = existing.docs.filter((document) => document.data()?.sourceSystem === "geo-rep-open-api" && !incomingDocumentIds.has(document.id));
    const writer = db.bulkWriter();
    staleApiRows.forEach((document) => writer.delete(document.ref));
    deduplicatedTransactions.forEach((row) => {
      writer.set(db.collection("salesTransactions").doc(`${period.periodKey.replace(/-/g, "")}-${row.transactionKey}`), {
        periodKey: period.periodKey, orderNumber: row.orderNumber, orderDate: row.orderDate, storeName: row.storeName || "Unknown store", storeCode: row.storeCode || "",
        region: row.region, mapped: row.mapped, mappingMethod: row.mappingMethod, sourceRep: row.sourceRep || "", mappedRep: row.mappedRep || "", rep: row.rep, repMissing: row.repMissing === true, sku: row.sku || "Unspecified SKU", product: row.product || row.sku || "Unspecified product",
        barcode: row.barcode || "", manager: row.manager || "Unassigned", orderedBy: row.orderedBy || "", status: row.status || "Unspecified", poNumber: row.poNumber || "",
        client: row.client || "", banner: row.banner || "", channel: row.channel || "", division: row.division || "", brand: row.brand || "", category: row.category || "",
        quantity: row.quantity, unitPrice: row.unitPrice, value: row.value, transactionKey: row.transactionKey, sourceFileId: `geo-rep-open-api-${period.periodKey}`,
        sourceSystem: "geo-rep-open-api", epodId: row.epodId || "", importedAt: FieldValue.serverTimestamp()
      }, { merge: true });
    });
    await writer.close();
    const persisted = await db.collection("salesTransactions").where("periodKey", "==", period.periodKey).get();
    const persistedRows = persisted.docs.map((doc) => doc.data());
    const uniqueOrders = new Set(persistedRows.map((row) => row.orderNumber)).size;
    const mappedRows = persistedRows.filter((row) => row.mapped).length;
    const unmappedRows = persistedRows.filter((row) => !row.mapped || !salesDashboardCleanText(row.region) || row.region === "Unmapped");
    const missingRepRows = persistedRows.filter((row) => row.repMissing === true || !salesDashboardCleanText(row.rep) || row.rep === "Unassigned");
    const summary = {
      periodKey: period.periodKey, sourceFileId: `geo-rep-open-api-${period.periodKey}`, sourceFileName: "Geo Rep Open API EPOD Details",
      reportStartDate: period.startDate, reportEndDate: period.endDate, detailSheet: "Geo Rep API EPOD Details",
      sourceRows: rows.length, uniqueSourceRows: deduplicatedTransactions.length, duplicateSourceRows: rows.length - deduplicatedTransactions.length,
      newRecords: newTransactions.length, existingRecords: deduplicatedTransactions.length - newTransactions.length,
      staleRowsRemoved: staleApiRows.length, fullMonthSnapshot: true, periodOrderLines: persistedRows.length,
      uniqueOrders, mappedRows, unmappedRows: unmappedRows.length, missingRegionRows: unmappedRows.length, missingRepRows: missingRepRows.length,
      missingOrderNumberRows: rows.filter((row) => !salesDashboardCleanText(row.orderNumber)).length,
      unmappedStoreCount: new Set(unmappedRows.map((row) => row.storeCode || row.storeName).filter(Boolean)).size,
      missingRepStoreCount: new Set(missingRepRows.map((row) => row.storeCode || row.storeName).filter(Boolean)).size,
      unmappedStoreSamples: [...new Set(unmappedRows.map((row) => row.storeName || row.storeCode).filter(Boolean))].slice(0, 25),
      missingRepSamples: [...new Set(missingRepRows.map((row) => row.storeName || row.storeCode).filter(Boolean))].slice(0, 25),
      storeMasterQuality: { sourceRows: masterData.sourceRows || 0, usableRows: masterData.entries.length, excludedRows: masterData.excludedRows || 0, duplicateKeyCount: masterData.duplicateKeyCount || 0 },
      totalQuantity: persistedRows.reduce((total, row) => total + Number(row.quantity || 0), 0),
      totalValue: persistedRows.reduce((total, row) => total + Number(row.value || 0), 0),
      source: "geo-rep-open-api", apiHeaderRows: epodsResult.records.length,
      completedAt: FieldValue.serverTimestamp()
    };
    summary.reconciliation = {
      inputRows: rows.length, uniqueInputRows: deduplicatedTransactions.length, duplicateSourceRows: summary.duplicateSourceRows,
      newRecords: summary.newRecords, existingRecords: summary.existingRecords, reconciled: true,
      monthToDateRows: summary.periodOrderLines, monthToDateOrders: summary.uniqueOrders,
      monthToDateValue: summary.totalValue, monthToDateQuantity: summary.totalQuantity
    };
    await Promise.all([
      importRef.set({ status: "completed", message: `${summary.newRecords.toLocaleString("en-ZA")} API order lines added; ${summary.existingRecords.toLocaleString("en-ZA")} already existed; ${summary.periodOrderLines.toLocaleString("en-ZA")} month-to-date dashboard rows available.`, ...summary, updatedAt: FieldValue.serverTimestamp() }, { merge: true }),
      db.collection("salesDashboardSnapshots").doc("current").set(summary, { merge: true }),
      db.collection("salesDashboardConfig").doc("current").set({ lastApiImport: { ...summary, completedAt: FieldValue.serverTimestamp() }, lastImport: { ...summary, completedAt: FieldValue.serverTimestamp() }, updatedAt: FieldValue.serverTimestamp() }, { merge: true })
    ]);
    return { status: "completed", importId: importRef.id, ...summary };
  } catch (error) {
    const message = optionalText(error?.message || error, 600) || "Geo Rep Open API sales import failed.";
    await importRef.set({ status: "failed", message, failedAt: FieldValue.serverTimestamp(), updatedAt: FieldValue.serverTimestamp() }, { merge: true });
    throw error;
  } finally {
    await fs.rm(tempDirectory, { recursive: true, force: true }).catch(() => {});
  }
}

async function queueGeoRepSalesTransactionImport({ run, sourceFileId, sourceFileName, parentRunId }) {
  if (!isGeoRepOrdersRetailer(run.retailerId) && run.workflowMode !== "geo-rep-sales-transactions") return null;
  const configDoc = await db.collection("salesDashboardConfig").doc("current").get();
  const config = configDoc.exists ? configDoc.data() : {};
  if (!config.storeMasterId) return { skipped: true, reason: "No Geo Rep Capture Orders Store Master is assigned." };
  const importRef = db.collection("salesTransactionImports").doc(sourceFileId);
  const existing = await importRef.get();
  if (existing.exists) return { importId: importRef.id, reused: true };
  const dates = reportDatesForRun(run);
  await importRef.set({
    sourceFileId, sourceFileName: sourceFileName || null, parentRunId: parentRunId || null,
    storeMasterId: config.storeMasterId, storeMasterName: config.storeMasterName || null,
    periodKey: dates.startDate.slice(0, 7), reportStartDate: dates.startDate, reportEndDate: dates.endDate,
    status: "queued", message: "Orders report saved. Importing the Transaction Report detail tab into sales analytics.",
    createdAt: FieldValue.serverTimestamp(), updatedAt: FieldValue.serverTimestamp()
  });
  return { importId: importRef.id, reused: false };
}

exports.saveGeoRepSalesStoreMaster = onCall({
  timeoutSeconds: 180, memory: "1GiB",
  cors: ["https://meridian-nexus.web.app", "https://meridian-nexus.firebaseapp.com"]
}, async (request) => {
  requireAdmin(request);
  const name = text(request.data.name, "Store master name", 120);
  const id = optionalText(request.data.id, 64) || geoRepOrdersStoreMasterId;
  const storagePath = text(request.data.storagePath, "Store master workbook", 500);
  if (!storagePath.startsWith(`geo-rep-sales-store-masters/${id}/`)) throw new HttpsError("invalid-argument", "The Geo Rep Capture Orders Store Master upload path is invalid.");
  const file = getStorage().bucket().file(storagePath);
  const [metadata] = await file.getMetadata().catch(() => { throw new HttpsError("not-found", "Upload the Geo Rep Capture Orders Store Master before saving it."); });
  if (Number(metadata.size) <= 0 || Number(metadata.size) > geoRepSalesStoreMasterMaxBytes) throw new HttpsError("invalid-argument", "The Geo Rep Capture Orders Store Master must be between 1 byte and 25 MB.");
  const validationDirectory = await fs.mkdtemp(path.join(os.tmpdir(), "nexus-geo-orders-master-"));
  let parsed;
  try {
    parsed = await readGeoRepSalesStoreMaster({ storagePath, sourceName: optionalText(request.data.sourceName, 240) }, validationDirectory);
  } catch (error) {
    throw new HttpsError("invalid-argument", String(error.message || error));
  } finally {
    await fs.rm(validationDirectory, { recursive: true, force: true }).catch(() => {});
  }
  const regionCount = new Set(parsed.entries.map((entry) => entry.region)).size;
  await db.collection("salesStoreMasters").doc(id).set({
    name, storagePath, sourceName: optionalText(request.data.sourceName, 240), storeCount: parsed.entries.length, regionCount,
    sheetName: parsed.sheetName, active: true, updatedAt: FieldValue.serverTimestamp(), updatedBy: request.auth.uid
  }, { merge: true });
  await db.collection("salesDashboardConfig").doc("current").set({
    storeMasterId: id, storeMasterName: name, storeMasterUpdatedAt: FieldValue.serverTimestamp(), updatedAt: FieldValue.serverTimestamp(), updatedBy: request.auth.uid
  }, { merge: true });
  const currentPeriod = localDateParts(new Date(), "Africa/Johannesburg").date.slice(0, 7);
  const remap = await remapGeoRepSalesTransactionsFromMaster(parsed, currentPeriod);
  await db.collection("salesDashboardConfig").doc("current").set({
    lastStoreMasterRemap: { ...remap, completedAt: FieldValue.serverTimestamp() }
  }, { merge: true });
  return { id, storeCount: parsed.entries.length, regionCount, sheetName: parsed.sheetName, remap };
});

exports.setupGeoRepSalesDashboard = onCall({
  cors: ["https://meridian-nexus.web.app", "https://meridian-nexus.firebaseapp.com"]
}, async (request) => {
  requireAdmin(request);
  const requestedMasterId = optionalText(request.data?.storeMasterId, 64);
  const configRef = db.collection("salesDashboardConfig").doc("current");
  const [configDoc, sourceRetailerDoc, sourceProfileDoc, ordersRetailerDoc, ordersSecretDoc] = await Promise.all([
    configRef.get(), db.collection("retailers").doc("geo-rep").get(), db.collection("extractionProfiles").doc("georep-form-report-steps").get(),
    db.collection("retailers").doc(geoRepOrdersRetailerId).get(), db.collection("retailerSecrets").doc(geoRepOrdersRetailerId).get()
  ]);
  if (!sourceRetailerDoc.exists || !sourceProfileDoc.exists) throw new HttpsError("failed-precondition", "The existing Geo Rep Capture workflow is required before Sales transactions can be set up.");
  if (!ordersRetailerDoc.exists || !ordersSecretDoc.exists) throw new HttpsError("failed-precondition", "Open the Geo Rep Sales transactions profile and save its portal username and password before setting up the Orders workflow.");
  const config = configDoc.exists ? configDoc.data() : {};
  const storeMasterId = requestedMasterId || config.storeMasterId;
  if (!storeMasterId) throw new HttpsError("failed-precondition", "Upload the Geo Rep Capture Orders Store Master first.");
  const masterDoc = await db.collection("salesStoreMasters").doc(storeMasterId).get();
  if (!masterDoc.exists) throw new HttpsError("not-found", "The selected Geo Rep Capture Orders Store Master is not available.");
  const sourceSteps = Array.isArray(sourceProfileDoc.data().steps) ? sourceProfileDoc.data().steps : [];
  const loginSteps = sourceSteps.slice(0, 7).map((step, index) => ({ ...step, id: `geo-orders-${String(index + 1).padStart(2, "0")}` }));
  if (loginSteps.length < 7) throw new HttpsError("failed-precondition", "The Geo Rep Capture Forms workflow does not contain the required login steps.");
  const steps = [...loginSteps, { id: "geo-orders-08", action: "geoRepDownloadTransactionReport", selector: "", value: "" }];
  const sourceRetailer = sourceRetailerDoc.data();
  const ordersRetailer = ordersRetailerDoc.data();
  const schedule = ordersRetailer.reportSchedule || {
    enabled: true, frequency: "daily", dateMode: "daily", time: "06:15", timezone: "Africa/Johannesburg", daysOfWeek: [0, 1, 2, 3, 4, 5, 6], businessDaysOnly: false
  };
  const batch = db.batch();
  batch.set(db.collection("extractionProfiles").doc(geoRepOrdersExtractionProfileId), {
    name: "Geo Rep Sales transactions", steps, stepCount: steps.length, workflowMode: "geo-rep-sales-transactions", updatedAt: FieldValue.serverTimestamp(), updatedBy: request.auth.uid
  }, { merge: true });
  batch.set(db.collection("retailers").doc(geoRepOrdersRetailerId), {
    name: ordersRetailer.name || "Geo Rep Sales transactions", webAddress: ordersRetailer.webAddress || sourceRetailer.webAddress, username: ordersRetailer.username || sourceRetailer.username,
    extractionProfileId: geoRepOrdersExtractionProfileId, extractionName: "Geo Rep Sales transactions", reportSchedule: schedule,
    sourceRetailerId: "geo-rep", salesDashboard: true, storeMasterId, updatedAt: FieldValue.serverTimestamp(), updatedBy: request.auth.uid
  }, { merge: true });
  batch.set(configRef, {
    storeMasterId, storeMasterName: masterDoc.data().name || null, transactionRetailerId: geoRepOrdersRetailerId,
    transactionExtractionProfileId: geoRepOrdersExtractionProfileId, setupStatus: "ready", setupCompletedAt: FieldValue.serverTimestamp(), updatedAt: FieldValue.serverTimestamp(), updatedBy: request.auth.uid
  }, { merge: true });
  await batch.commit();
  return { retailerId: geoRepOrdersRetailerId, extractionProfileId: geoRepOrdersExtractionProfileId, storeMasterId };
});

exports.reconcileGeoRepSalesTransactionImport = onCall({ timeoutSeconds: 120, memory: "512MiB", cors: ["https://meridian-nexus.web.app", "https://meridian-nexus.firebaseapp.com"] }, async (request) => {
  requireAdmin(request);
  const configDocument = await db.collection("salesDashboardConfig").doc("current").get();
  const config = configDocument.exists ? configDocument.data() || {} : {};
  const sourceFileId = optionalText(request.data?.sourceFileId, 160) || optionalText(config.lastImport?.sourceFileId, 160);
  if (!config.storeMasterId) throw new HttpsError("failed-precondition", "Save the Geo Rep Capture Orders Store Master before reconciling transactions.");
  if (!sourceFileId) throw new HttpsError("failed-precondition", "No stored Geo Rep Capture Transaction Report is available to reconcile.");
  const sourceFile = await db.collection("files").doc(sourceFileId).get();
  if (!sourceFile.exists) throw new HttpsError("not-found", "The latest stored Transaction Report is not available.");
  const source = sourceFile.data() || {};
  const currentPeriod = optionalText(source.reportStartDate, 10).slice(0, 7) || localDateParts(new Date(), "Africa/Johannesburg").date.slice(0, 7);
  const importRef = db.collection("salesTransactionImports").doc();
  await importRef.set({
    sourceFileId, sourceFileName: source.name || source.originalName || null, parentRunId: source.extractionRunId || null,
    storeMasterId: config.storeMasterId, storeMasterName: config.storeMasterName || null,
    periodKey: currentPeriod, reportStartDate: optionalText(source.reportStartDate, 10) || `${currentPeriod}-01`, reportEndDate: optionalText(source.reportEndDate, 10) || localDateParts(new Date(), "Africa/Johannesburg").date,
    status: "queued", message: "Reconciliation queued: refreshing Transaction Report mappings and data-quality controls.",
    reconciliationOfImportId: optionalText(config.lastImport?.sourceFileId, 160) || null,
    createdAt: FieldValue.serverTimestamp(), updatedAt: FieldValue.serverTimestamp()
  });
  await recordAccessAudit(requestActor(request), "sales-transaction-reconciliation-queued", { retailerId: geoRepOrdersRetailerId, retailerName: "Geo Rep Sales transactions", result: "queued", message: `Sales Transaction reconciliation queued as ${importRef.id}.` });
  return { importId: importRef.id, sourceFileId };
});

exports.runGeoRepSalesDashboardApiImport = onCall({
  secrets: [geoRepOpenApiId, geoRepOpenApiKey],
  timeoutSeconds: 540,
  memory: "2GiB",
  cors: ["https://meridian-nexus.web.app", "https://meridian-nexus.firebaseapp.com"]
}, async (request) => {
  requireAdmin(request);
  const actor = requestActor(request);
  try {
    const result = await importGeoRepSalesTransactionsFromApi({ trigger: "manual", actor });
    await recordAccessAudit(actor, "geo-rep-sales-api-import", {
      retailerId: geoRepOrdersRetailerId,
      retailerName: "Geo Rep Sales transactions",
      result: result.status,
      message: `Geo Rep Open API sales dashboard import finished as ${result.status}.`
    });
    return result;
  } catch (error) {
    const message = optionalText(error?.message || error, 500);
    await recordAccessAudit(actor, "geo-rep-sales-api-import", {
      retailerId: geoRepOrdersRetailerId,
      retailerName: "Geo Rep Sales transactions",
      result: "failed",
      message
    });
    throw new HttpsError("internal", message);
  }
});

exports.runScheduledGeoRepSalesDashboardApiImport = onSchedule({
  schedule: "0 8 * * *",
  timeZone: "Africa/Johannesburg",
  timeoutSeconds: 540,
  memory: "2GiB",
  concurrency: 1,
  secrets: [geoRepOpenApiId, geoRepOpenApiKey]
}, async () => {
  try {
    const result = await importGeoRepSalesTransactionsFromApi({ trigger: "scheduled" });
    await db.collection("integrationHealth").doc("geo-rep-sales-api").set({
      provider: "Geo Rep Open API Sales Dashboard",
      status: result.status === "completed" ? "connected" : result.status,
      lastImportAt: FieldValue.serverTimestamp(),
      lastImportId: result.importId || null,
      lastImportSummary: {
        periodKey: result.periodKey || null,
        sourceRows: Number(result.sourceRows || 0),
        uniqueOrders: Number(result.uniqueOrders || 0),
        periodOrderLines: Number(result.periodOrderLines || 0),
        totalValue: Number(result.totalValue || 0)
      },
      updatedAt: FieldValue.serverTimestamp()
    }, { merge: true });
    return result;
  } catch (error) {
    const message = optionalText(error?.message || error, 600);
    await db.collection("integrationHealth").doc("geo-rep-sales-api").set({
      provider: "Geo Rep Open API Sales Dashboard",
      status: "failed",
      error: message,
      updatedAt: FieldValue.serverTimestamp()
    }, { merge: true });
    console.error("Scheduled Geo Rep Open API sales dashboard import failed", error);
    return null;
  }
});

exports.importGeoRepSalesTransactionReport = onDocumentCreated({ document: "salesTransactionImports/{importId}", timeoutSeconds: 540, memory: "4GiB", cpu: 2, maxInstances: 2, concurrency: 1 }, async (event) => {
  const importRef = event.data.ref;
  const job = event.data.data();
  if (job.source === "geo-rep-open-api") return;
  const tempDirectory = await fs.mkdtemp(path.join(os.tmpdir(), "nexus-geo-orders-import-"));
  try {
    await importRef.set({ status: "running", message: "Reading Geo Rep Capture Transaction Report detail rows and applying the current Store Master regions.", startedAt: FieldValue.serverTimestamp(), updatedAt: FieldValue.serverTimestamp() }, { merge: true });
    const [fileDoc, masterDoc] = await Promise.all([db.collection("files").doc(job.sourceFileId).get(), db.collection("salesStoreMasters").doc(job.storeMasterId).get()]);
    if (!fileDoc.exists) throw new Error("The downloaded Geo Rep Capture Transaction Report is no longer available.");
    if (!masterDoc.exists) throw new Error("The selected Geo Rep Capture Orders Store Master is no longer available.");
    const file = fileDoc.data();
    const master = masterDoc.data();
    const [masterData, transactionData] = await Promise.all([
      readGeoRepSalesStoreMaster(master, tempDirectory),
      readGeoRepSalesTransactions(file, tempDirectory, job.reportEndDate || job.reportStartDate)
    ]);
    const byCode = new Map();
    const byName = new Map();
    masterData.entries.forEach((entry) => {
      if (entry.storeCode) byCode.set(salesDashboardNormalise(entry.storeCode), entry);
      if (entry.storeName) byName.set(salesDashboardNormalise(entry.storeName), entry);
    });
    const transactions = transactionData.rows.map((row) => {
      const codeMatch = row.storeCode && byCode.get(salesDashboardNormalise(row.storeCode));
      const nameMatch = !codeMatch && row.storeName && byName.get(salesDashboardNormalise(row.storeName));
      const matched = codeMatch || nameMatch || null;
      const sourceRep = salesDashboardCleanText(row.rep, 160);
      const mappedRep = salesDashboardCleanText(matched?.rep, 160);
      return {
        ...row,
        region: salesDashboardCleanText(matched?.region, 120) || "Unmapped",
        client: salesDashboardCleanText(row.client || matched?.client, 120),
        banner: salesDashboardCleanText(matched?.banner, 120),
        channel: salesDashboardCleanText(row.channel || matched?.channel, 120),
        division: salesDashboardCleanText(row.division || matched?.division, 120),
        mapped: Boolean(matched),
        mappingMethod: codeMatch ? "store-code" : nameMatch ? "store-name" : "unmapped",
        sourceRep,
        mappedRep,
        rep: sourceRep || mappedRep || "Unassigned",
        repMissing: !sourceRep && !mappedRep
      };
    });
    const uniqueTransactions = new Map();
    transactions.forEach((row) => {
      const transactionKey = crypto.createHash("sha256").update([
        job.periodKey, row.orderNumber, row.barcode || row.sku || row.product,
        row.storeCode || row.storeName, row.orderDate, row.quantity, row.value
      ].map(salesDashboardNormalise).join("|")).digest("hex").slice(0, 40);
      if (!uniqueTransactions.has(transactionKey)) uniqueTransactions.set(transactionKey, { ...row, transactionKey });
    });
    const deduplicatedTransactions = [...uniqueTransactions.values()];
    const existing = await db.collection("salesTransactions").where("periodKey", "==", job.periodKey).get();
    const reportStartDate = optionalText(job.reportStartDate, 10);
    const reportEndDate = optionalText(job.reportEndDate, 10);
    const isMonthToDateSnapshot = /^\d{4}-\d{2}-01$/.test(reportStartDate) && /^\d{4}-\d{2}-\d{2}$/.test(reportEndDate);
    const incomingDocumentIds = new Set(deduplicatedTransactions.map((row) => `${job.periodKey.replace(/-/g, "")}-${row.transactionKey}`));
    const staleSnapshotDocuments = isMonthToDateSnapshot
      ? existing.docs.filter((document) => {
        const row = document.data() || {};
        const orderDate = optionalText(row.orderDate, 10);
        const fallsWithinReportRange = orderDate >= reportStartDate && orderDate <= reportEndDate;
        const belongsToThisReport = fallsWithinReportRange || row.sourceFileId === job.sourceFileId;
        const legacyPartialRow = !optionalText(row.transactionKey, 64) || !optionalText(row.mappingMethod, 40);
        return belongsToThisReport && (legacyPartialRow || !incomingDocumentIds.has(document.id));
      })
      : [];
    // Geo Rep delivers a month-to-date snapshot. Reconcile the covered dates so
    // legacy or partial cache rows cannot inflate dashboard totals.
    if (staleSnapshotDocuments.length) {
      const cleanupWriter = db.bulkWriter();
      staleSnapshotDocuments.forEach((document) => cleanupWriter.delete(document.ref));
      await cleanupWriter.close();
    }
    const retainedExistingIds = new Set(existing.docs
      .filter((document) => !staleSnapshotDocuments.some((stale) => stale.id === document.id))
      .map((document) => document.id));
    const newTransactions = deduplicatedTransactions.filter((row) => !retainedExistingIds.has(`${job.periodKey.replace(/-/g, "")}-${row.transactionKey}`));
    const writer = db.bulkWriter();
    deduplicatedTransactions.forEach((row) => {
      // Deterministic document IDs make an overlapping scheduled/manual import
      // idempotent. Existing rows are refreshed with the latest Store Master
      // mapping without creating another transaction line.
      writer.set(db.collection("salesTransactions").doc(`${job.periodKey.replace(/-/g, "")}-${row.transactionKey}`), {
        periodKey: job.periodKey, orderNumber: row.orderNumber, orderDate: row.orderDate, storeName: row.storeName || "Unknown store", storeCode: row.storeCode || "",
        region: row.region, mapped: row.mapped, mappingMethod: row.mappingMethod, sourceRep: row.sourceRep || "", mappedRep: row.mappedRep || "", rep: row.rep, repMissing: row.repMissing === true, sku: row.sku || "Unspecified SKU", product: row.product || row.sku || "Unspecified product",
        barcode: row.barcode || "", manager: row.manager || "Unassigned", orderedBy: row.orderedBy || "", status: row.status || "Unspecified", poNumber: row.poNumber || "",
        client: row.client || "", banner: row.banner || "", channel: row.channel || "", division: row.division || "", brand: row.brand || "", category: row.category || "",
        quantity: row.quantity, unitPrice: row.unitPrice, value: row.value, transactionKey: row.transactionKey, sourceFileId: job.sourceFileId,
        importedAt: FieldValue.serverTimestamp()
      }, { merge: true });
    });
    await writer.close();
    const persisted = await db.collection("salesTransactions").where("periodKey", "==", job.periodKey).get();
    const persistedRows = persisted.docs.map((doc) => doc.data());
    const uniqueOrders = new Set(persistedRows.map((row) => row.orderNumber)).size;
    const mappedRows = persistedRows.filter((row) => row.mapped).length;
    const unmappedRows = persistedRows.filter((row) => !row.mapped || !salesDashboardCleanText(row.region) || row.region === "Unmapped");
    const missingRepRows = persistedRows.filter((row) => row.repMissing === true || !salesDashboardCleanText(row.rep) || row.rep === "Unassigned");
    const invalidOrderRows = transactionData.rows.filter((row) => !salesDashboardCleanText(row.orderNumber));
    const duplicateSourceRows = transactionData.rows.length - deduplicatedTransactions.length;
    const reconciliation = {
      inputRows: transactionData.rows.length,
      uniqueInputRows: deduplicatedTransactions.length,
      duplicateSourceRows,
      newRecords: newTransactions.length,
      existingRecords: deduplicatedTransactions.length - newTransactions.length,
      reconciled: newTransactions.length + (deduplicatedTransactions.length - newTransactions.length) === deduplicatedTransactions.length,
      monthToDateRows: persistedRows.length,
      monthToDateOrders: uniqueOrders,
      monthToDateValue: persistedRows.reduce((total, row) => total + Number(row.value || 0), 0),
      monthToDateQuantity: persistedRows.reduce((total, row) => total + Number(row.quantity || 0), 0)
    };
    const summary = {
      periodKey: job.periodKey, sourceFileId: job.sourceFileId, sourceFileName: job.sourceFileName || file.name || null,
      reportStartDate: job.reportStartDate, reportEndDate: job.reportEndDate, detailSheet: transactionData.sheetName,
      sourceRows: transactionData.rows.length, uniqueSourceRows: deduplicatedTransactions.length, duplicateSourceRows,
      newRecords: newTransactions.length, existingRecords: deduplicatedTransactions.length - newTransactions.length,
      staleRowsRemoved: staleSnapshotDocuments.length, fullMonthSnapshot: isMonthToDateSnapshot,
      periodOrderLines: persistedRows.length, uniqueOrders, mappedRows, unmappedRows: unmappedRows.length,
      missingRegionRows: unmappedRows.length, missingRepRows: missingRepRows.length, missingOrderNumberRows: invalidOrderRows.length,
      unmappedStoreCount: new Set(unmappedRows.map((row) => row.storeCode || row.storeName).filter(Boolean)).size,
      missingRepStoreCount: new Set(missingRepRows.map((row) => row.storeCode || row.storeName).filter(Boolean)).size,
      unmappedStoreSamples: [...new Set(unmappedRows.map((row) => row.storeName || row.storeCode).filter(Boolean))].slice(0, 25),
      missingRepSamples: [...new Set(missingRepRows.map((row) => row.storeName || row.storeCode).filter(Boolean))].slice(0, 25),
      storeMasterQuality: { sourceRows: masterData.sourceRows || 0, usableRows: masterData.entries.length, excludedRows: masterData.excludedRows || 0, duplicateKeyCount: masterData.duplicateKeyCount || 0 },
      reconciliation,
      totalQuantity: reconciliation.monthToDateQuantity, totalValue: reconciliation.monthToDateValue,
      completedAt: FieldValue.serverTimestamp()
    };
    await Promise.all([
      importRef.set({ status: "completed", message: `${newTransactions.length.toLocaleString("en-ZA")} new order lines added; ${(deduplicatedTransactions.length - newTransactions.length).toLocaleString("en-ZA")} already existed; ${staleSnapshotDocuments.length.toLocaleString("en-ZA")} stale cache rows reconciled. ${persistedRows.length.toLocaleString("en-ZA")} month-to-date lines are available from ${transactionData.sheetName}.`, ...summary, updatedAt: FieldValue.serverTimestamp() }, { merge: true }),
      db.collection("salesDashboardSnapshots").doc("current").set(summary, { merge: true }),
      db.collection("salesDashboardConfig").doc("current").set({ lastImport: { ...summary, completedAt: FieldValue.serverTimestamp() }, updatedAt: FieldValue.serverTimestamp() }, { merge: true })
    ]);
  } catch (error) {
    console.error("Geo Rep Capture sales transaction import failed", event.params.importId, error);
    await importRef.set({ status: "failed", message: String(error.message || error).slice(0, 500), failedAt: FieldValue.serverTimestamp(), updatedAt: FieldValue.serverTimestamp() }, { merge: true });
  } finally {
    await fs.rm(tempDirectory, { recursive: true, force: true }).catch(() => {});
  }
});

function salesDashboardBreakdown(rows, field, limit = 10, sortBy = "value") {
  const grouped = new Map();
  rows.forEach((row) => {
    const label = salesDashboardCleanText(row[field], 120) || "Unassigned";
    const current = grouped.get(label) || { label, value: 0, quantity: 0, orders: new Set() };
    current.value += Number(row.value || 0);
    current.quantity += Number(row.quantity || 0);
    current.orders.add(row.orderNumber);
    grouped.set(label, current);
  });
  return [...grouped.values()].map((item) => ({ ...item, orders: item.orders.size })).sort((left, right) => Number(right[sortBy] || 0) - Number(left[sortBy] || 0) || right.value - left.value || right.quantity - left.quantity).slice(0, limit);
}

function salesDashboardMatchesFilters(row, filters = {}) {
  return (!filters.region || row.region === filters.region)
    && (!filters.rep || row.rep === filters.rep)
    && (!filters.store || row.storeName === filters.store)
    && (!filters.sku || row.sku === filters.sku)
    && (!filters.product || row.product === filters.product)
    && (!filters.manager || row.manager === filters.manager)
    && (!filters.status || row.status === filters.status)
    && (!filters.client || row.client === filters.client)
    && (!filters.division || row.division === filters.division)
    && (!filters.channel || row.channel === filters.channel)
    && (!filters.retailer || row.banner === filters.retailer)
    && (!filters.brand || row.brand === filters.brand)
    && (!filters.category || row.category === filters.category);
}

function salesDashboardPeriodKeyOffset(periodKey, monthsBack = 0) {
  const match = String(periodKey || "").match(/^(\d{4})-(\d{2})$/);
  if (!match) return periodKey;
  const date = new Date(Date.UTC(Number(match[1]), Number(match[2]) - 1 - Math.max(0, Number(monthsBack) || 0), 1));
  return `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, "0")}`;
}

function salesDashboardDistinctCount(rows, field) {
  return new Set(rows.map((row) => salesDashboardCleanText(row[field], 160)).filter(Boolean)).size;
}

function salesDashboardOrderBreakdown(rows, limit = 10) {
  const grouped = new Map();
  rows.forEach((row) => {
    const label = salesDashboardCleanText(row.orderNumber, 160) || "Unassigned";
    const current = grouped.get(label) || { label, value: 0, quantity: 0, orders: 1 };
    current.value += Number(row.value || 0);
    current.quantity += Number(row.quantity || 0);
    grouped.set(label, current);
  });
  return [...grouped.values()]
    .sort((left, right) => right.value - left.value || right.quantity - left.quantity)
    .slice(0, limit);
}

function salesDashboardDetailRow(row) {
  return {
    orderDate: row.orderDate || "",
    orderNumber: row.orderNumber || "",
    storeName: row.storeName || "",
    storeCode: row.storeCode || "",
    region: row.region || "Unmapped",
    rep: row.rep || "Unassigned",
    manager: row.manager || "",
    product: row.product || "",
    sku: row.sku || "",
    quantity: Number(row.quantity || 0),
    value: Number(row.value || 0),
    status: row.status || "",
    mapped: row.mapped === true
  };
}

function salesDashboardDrilldown(metric, rows, latestImport, page) {
  const orderCount = new Set(rows.map((row) => row.orderNumber).filter(Boolean)).size;
  const salesValue = rows.reduce((total, row) => total + Number(row.value || 0), 0);
  const quantity = rows.reduce((total, row) => total + Number(row.quantity || 0), 0);
  const stores = salesDashboardDistinctCount(rows, "storeName");
  const reps = salesDashboardDistinctCount(rows, "rep");
  const mappedRows = rows.filter((row) => row.mapped === true).length;
  const unmappedRows = rows.length - mappedRows;
  const sortNewest = (left, right) => `${right.orderDate || ""}|${right.orderNumber || ""}`.localeCompare(`${left.orderDate || ""}|${left.orderNumber || ""}`);
  const base = {
    title: "Sales analysis",
    subtitle: "Selected Geo Rep Capture transaction detail.",
    primary: { label: "Sales value", value: salesValue, format: "currency", note: `${orderCount.toLocaleString("en-ZA")} unique orders` },
    insights: [
      { label: "Units", value: quantity, format: "number" },
      { label: "Stores", value: stores, format: "number" },
      { label: "Average order", value: orderCount ? salesValue / orderCount : 0, format: "currency" }
    ],
    chart: { eyebrow: "Product mix", title: "Sales value by product", format: "currency", rows: salesDashboardBreakdown(rows, "product", 10) },
    recordTitle: "Transaction lines",
    recordRows: [...rows].sort(sortNewest)
  };

  if (metric === "orders") {
    Object.assign(base, {
      title: "Order analysis", subtitle: "Unique orders within the current selection.",
      primary: { label: "Unique orders", value: orderCount, format: "number", note: `${rows.length.toLocaleString("en-ZA")} order lines` },
      insights: [{ label: "Sales value", value: salesValue, format: "currency" }, { label: "Units", value: quantity, format: "number" }, { label: "Active stores", value: stores, format: "number" }],
      chart: { eyebrow: "Order value", title: "Largest orders", format: "currency", rows: salesDashboardOrderBreakdown(rows, 10) },
      recordTitle: "Order lines"
    });
  } else if (metric === "units") {
    Object.assign(base, {
      title: "Unit analysis", subtitle: "Ordered units and the product mix behind them.",
      primary: { label: "Ordered units", value: quantity, format: "number", note: `${orderCount.toLocaleString("en-ZA")} unique orders` },
      insights: [{ label: "Sales value", value: salesValue, format: "currency" }, { label: "Units per order", value: orderCount ? quantity / orderCount : 0, format: "number1" }, { label: "Product SKUs", value: salesDashboardDistinctCount(rows, "sku"), format: "number" }],
      chart: { eyebrow: "Volume", title: "Units by product SKU", format: "number", rows: salesDashboardBreakdown(rows, "sku", 10, "quantity") },
      recordTitle: "Highest-volume order lines",
      recordRows: [...rows].sort((left, right) => Number(right.quantity || 0) - Number(left.quantity || 0) || sortNewest(left, right))
    });
  } else if (metric === "average-order") {
    Object.assign(base, {
      title: "Average order analysis", subtitle: "Average transaction value across the current selection.",
      primary: { label: "Average order value", value: orderCount ? salesValue / orderCount : 0, format: "currency", note: `${orderCount.toLocaleString("en-ZA")} unique orders` },
      insights: [{ label: "Sales value", value: salesValue, format: "currency" }, { label: "Units per order", value: orderCount ? quantity / orderCount : 0, format: "number1" }, { label: "Orders", value: orderCount, format: "number" }],
      chart: { eyebrow: "Order value", title: "Largest orders", format: "currency", rows: salesDashboardOrderBreakdown(rows, 10) },
      recordTitle: "Transaction lines"
    });
  } else if (metric === "stores") {
    Object.assign(base, {
      title: "Store coverage", subtitle: "Active stores with orders in the current selection.",
      primary: { label: "Active stores", value: stores, format: "number", note: `${mappedRows.toLocaleString("en-ZA")} lines mapped to a region` },
      insights: [{ label: "Orders", value: orderCount, format: "number" }, { label: "Sales value", value: salesValue, format: "currency" }, { label: "Regions", value: salesDashboardDistinctCount(rows.filter((row) => row.region !== "Unmapped"), "region"), format: "number" }],
      chart: { eyebrow: "Store performance", title: "Sales value by store", format: "currency", rows: salesDashboardBreakdown(rows, "storeName", 10) },
      recordTitle: "Store order lines",
      recordRows: [...rows].sort((left, right) => `${left.storeName || ""}|${left.orderDate || ""}`.localeCompare(`${right.storeName || ""}|${right.orderDate || ""}`))
    });
  } else if (metric === "reps") {
    Object.assign(base, {
      title: "Rep performance", subtitle: "Active reps and the orders assigned to them.",
      primary: { label: "Active reps", value: reps, format: "number", note: `${salesDashboardDistinctCount(rows, "manager").toLocaleString("en-ZA")} managers in selection` },
      insights: [{ label: "Orders", value: orderCount, format: "number" }, { label: "Sales value", value: salesValue, format: "currency" }, { label: "Stores", value: stores, format: "number" }],
      chart: { eyebrow: "Rep performance", title: "Sales value by rep", format: "currency", rows: salesDashboardBreakdown(rows, "rep", 10) },
      recordTitle: "Rep order lines",
      recordRows: [...rows].sort((left, right) => `${left.rep || ""}|${left.orderDate || ""}`.localeCompare(`${right.rep || ""}|${right.orderDate || ""}`))
    });
  } else if (metric === "mapped") {
    const mappedPercent = rows.length ? (mappedRows / rows.length) * 100 : 0;
    Object.assign(base, {
      title: "Region mapping quality", subtitle: "Store Master coverage for the current order selection.",
      primary: { label: "Mapped to region", value: mappedPercent, format: "percent", note: `${mappedRows.toLocaleString("en-ZA")} of ${rows.length.toLocaleString("en-ZA")} lines mapped` },
      insights: [{ label: "Unmapped lines", value: unmappedRows, format: "number" }, { label: "Unmapped stores", value: new Set(rows.filter((row) => !row.mapped).map((row) => row.storeCode || row.storeName).filter(Boolean)).size, format: "number" }, { label: "Mapped regions", value: salesDashboardDistinctCount(rows.filter((row) => row.mapped), "region"), format: "number" }],
      chart: { eyebrow: "Region coverage", title: "Sales value by mapped region", format: "currency", rows: salesDashboardBreakdown(rows, "region", 10) },
      recordTitle: "Mapping review lines",
      recordRows: [...rows].sort((left, right) => Number(left.mapped === true) - Number(right.mapped === true) || sortNewest(left, right))
    });
  } else if (metric === "latest-import") {
    Object.assign(base, {
      title: "Latest import review", subtitle: "Current month data reconciliation and latest import outcome.",
      primary: { label: "New lines in latest import", value: Number(latestImport?.newRecords || 0), format: "number", note: `${Number(latestImport?.existingRecords || 0).toLocaleString("en-ZA")} source lines already existed` },
      insights: [{ label: "Source rows", value: Number(latestImport?.sourceRows || 0), format: "number" }, { label: "Duplicates removed", value: Number(latestImport?.duplicateSourceRows || 0), format: "number" }, { label: "Current month lines", value: rows.length, format: "number" }],
      chart: { eyebrow: "Daily movement", title: "Sales value by order date", format: "currency", rows: salesDashboardBreakdown(rows, "orderDate", 31).sort((left, right) => left.label.localeCompare(right.label)) },
      recordTitle: "Latest month transaction lines"
    });
  }

  const pageSize = 25;
  const totalRows = base.recordRows.length;
  const pageCount = Math.max(1, Math.ceil(totalRows / pageSize));
  const selectedPage = Math.min(Math.max(1, Number(page) || 1), pageCount);
  return {
    ...base,
    recordRows: base.recordRows.slice((selectedPage - 1) * pageSize, selectedPage * pageSize).map(salesDashboardDetailRow),
    totalRows,
    page: selectedPage,
    pageCount,
    pageSize
  };
}

function salesInsightsSnapshotRows(value) {
  if (Array.isArray(value)) return value;
  if (Array.isArray(value?.rows)) return value.rows;
  if (Array.isArray(value?.data)) return value.data;
  return [];
}

function salesInsightsSnapshotNumber(value) {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? numeric : 0;
}

function salesInsightsSnapshotPeriodKey(value) {
  const match = String(value || "").match(/^(\d{4})-(\d{2})/);
  return match ? `${match[1]}-${match[2]}` : "";
}

function salesInsightsSnapshotOptions(value, fields = []) {
  const candidates = Array.isArray(value) ? value : salesInsightsSnapshotRows(value);
  return [...new Set(candidates.map((item) => {
    if (typeof item === "string" || typeof item === "number") return String(item).trim();
    for (const field of fields) {
      const resolved = optionalText(item?.[field], 240);
      if (resolved) return resolved;
    }
    return "";
  }).filter(Boolean))].sort((left, right) => left.localeCompare(right));
}

function salesInsightsSnapshotBreakdown(value, fields = []) {
  const grouped = new Map();
  salesInsightsSnapshotRows(value).forEach((row) => {
    const label = fields.map((field) => optionalText(row?.[field], 240)).find(Boolean) || "Unassigned";
    const item = grouped.get(label) || { label, value: 0, quantity: 0, orders: 0 };
    item.value += salesInsightsSnapshotNumber(row?.sales_value ?? row?.cur_value ?? row?.value);
    item.quantity += salesInsightsSnapshotNumber(row?.sales_units ?? row?.cur_units ?? row?.quantity ?? row?.units);
    item.orders += salesInsightsSnapshotNumber(row?.orders ?? row?.order_count);
    grouped.set(label, item);
  });
  return [...grouped.values()].sort((left, right) => right.value - left.value || left.label.localeCompare(right.label));
}

function salesInsightsSnapshotDimensionBreakdown(value) {
  return salesInsightsSnapshotRows(value).map((row) => ({
    label: optionalText(row?.dim, 240) || "Unassigned",
    value: salesInsightsSnapshotNumber(row?.cur_value),
    quantity: salesInsightsSnapshotNumber(row?.cur_units),
    orders: 0,
    priorValue: salesInsightsSnapshotNumber(row?.ly_value),
    priorQuantity: salesInsightsSnapshotNumber(row?.ly_units),
    deltaValue: salesInsightsSnapshotNumber(row?.delta_value),
    deltaQuantity: salesInsightsSnapshotNumber(row?.delta_units)
  })).filter((row) => row.label !== "Unassigned").sort((left, right) => right.value - left.value || left.label.localeCompare(right.label));
}

function salesInsightsSnapshotDimensionPriorBreakdown(value) {
  return salesInsightsSnapshotRows(value).map((row) => ({
    label: optionalText(row?.dim, 240) || "Unassigned",
    value: salesInsightsSnapshotNumber(row?.ly_value),
    quantity: salesInsightsSnapshotNumber(row?.ly_units),
    orders: 0
  })).filter((row) => row.label !== "Unassigned").sort((left, right) => right.value - left.value || left.label.localeCompare(right.label));
}

function salesInsightsSnapshotMonthlyTrend(value) {
  return salesInsightsSnapshotRows(value).map((row) => ({
    label: salesInsightsSnapshotPeriodKey(row?.month),
    value: salesInsightsSnapshotNumber(row?.sales_value),
    quantity: salesInsightsSnapshotNumber(row?.sales_units),
    orders: 0
  })).filter((row) => row.label).sort((left, right) => left.label.localeCompare(right.label));
}

function salesInsightsSnapshotTrailingMetrics(monthly, months) {
  const current = monthly.slice(-months);
  const prior = monthly.slice(-(months * 2), -months);
  return {
    salesValue: current.reduce((total, row) => total + row.value, 0),
    quantity: current.reduce((total, row) => total + row.quantity, 0),
    priorSalesValue: prior.reduce((total, row) => total + row.value, 0),
    priorQuantity: prior.reduce((total, row) => total + row.quantity, 0)
  };
}

function salesInsightsSnapshotCard(cards, key) {
  return salesInsightsSnapshotRows(cards).find((card) => optionalText(card?.key, 80) === key) || {};
}

function salesInsightsSnapshotDashboard(snapshot, request = {}) {
  const payload = snapshot?.payload || {};
  const sourceIsSharePoint = optionalText(snapshot?.source, 120) === "sharepoint-sales-duckdb";
  const filters = request.filters || {};
  const requestedWindow = Math.floor(Number(request.windowMonths || 12));
  const windowMonths = [1, 3, 6, 12].includes(requestedWindow) ? requestedWindow : 12;
  const client = optionalText(filters.client, 160);
  const allMonthly = salesInsightsSnapshotMonthlyTrend(payload.monthlyTrend);
  const clientMonthly = client
    ? salesInsightsSnapshotRows(payload.clientMonthly).filter((row) => optionalText(row?.client, 160) === client).map((row) => ({
      label: salesInsightsSnapshotPeriodKey(row?.month), value: salesInsightsSnapshotNumber(row?.sales_value), quantity: salesInsightsSnapshotNumber(row?.sales_units), orders: 0,
      stores: salesInsightsSnapshotNumber(row?.store_count)
    })).filter((row) => row.label).sort((left, right) => left.label.localeCompare(right.label))
    : allMonthly;
  const allSelectedMonthly = clientMonthly.length ? clientMonthly : allMonthly;
  const monthly = allSelectedMonthly.slice(-windowMonths);
  const priorMonthly = allSelectedMonthly.slice(-(windowMonths * 2), -windowMonths);
  const fallbackMetrics = salesInsightsSnapshotTrailingMetrics(allSelectedMonthly, windowMonths);
  const rollingKey = windowMonths === 1 ? "mtd" : `p${windowMonths}m`;
  const rolling = payload.rollingSummary?.[rollingKey] || {};
  const sourceMetrics = client ? fallbackMetrics : {
    salesValue: salesInsightsSnapshotNumber(rolling.sales_value) || fallbackMetrics.salesValue,
    quantity: salesInsightsSnapshotNumber(rolling.sales_units) || fallbackMetrics.quantity,
    priorSalesValue: fallbackMetrics.priorSalesValue,
    priorQuantity: fallbackMetrics.priorQuantity
  };
  const latestMonth = salesInsightsSnapshotPeriodKey(payload.meta?.latest_month || payload.summary?.month || snapshot.latestMonth);
  const storesCard = salesInsightsSnapshotCard(payload.kpiCards, "stores");
  const averageUnitPrice = sourceMetrics.quantity ? sourceMetrics.salesValue / sourceMetrics.quantity : 0;
  const averageMonthValue = windowMonths ? sourceMetrics.salesValue / windowMonths : 0;
  const rows = salesInsightsSnapshotNumber(payload.meta?.row_count || snapshot.rowCount);
  const currentPeriods = new Set(monthly.map((row) => row.label));
  const priorPeriods = new Set(priorMonthly.map((row) => row.label));
  const rowsForPeriods = (value, periods) => salesInsightsSnapshotRows(value).filter((row) => periods.has(salesInsightsSnapshotPeriodKey(row?.month)));
  const byCategory = salesInsightsSnapshotBreakdown(rowsForPeriods(payload.categoryMonthly, currentPeriods), ["category", "dim", "label"]);
  const priorByCategory = salesInsightsSnapshotBreakdown(rowsForPeriods(payload.categoryMonthly, priorPeriods), ["category", "dim", "label"]);
  const byBrand = salesInsightsSnapshotDimensionBreakdown(payload.brandBreakdown);
  const byRegion = salesInsightsSnapshotDimensionBreakdown(payload.regionBreakdown);
  const byRetailer = salesInsightsSnapshotDimensionBreakdown(payload.bannerBreakdown);
  const byRep = salesInsightsSnapshotBreakdown(payload.reps, ["rep", "rep_name", "name", "label"]);
  const byStore = salesInsightsSnapshotBreakdown(payload.growingStores, ["store", "store_name", "name", "label"]);
  return {
    source: {
      kind: sourceIsSharePoint ? "firebase-sales-insights" : "historical-sales-insights",
      name: sourceIsSharePoint ? "SharePoint sales.duckdb mirrored in Firebase Storage" : "Sales Insights sales.duckdb snapshot",
      generatedAt: payload.meta?.generated_at || snapshot.generatedAt || null
    },
    periodKey: latestMonth,
    startPeriodKey: monthly[0]?.label || latestMonth,
    windowMonths,
    latestImport: {
      status: "completed", detailSheet: sourceIsSharePoint ? "Firebase Storage Sales Insights master" : "sales.duckdb historical Sales Insights", periodOrderLines: rows,
      completedAt: payload.meta?.generated_at || snapshot.generatedAt || null, newRecords: 0, existingRecords: rows
    },
    availableFilters: {
      clients: salesInsightsSnapshotOptions(payload.meta?.clients, []),
      categories: salesInsightsSnapshotOptions(payload.categories, ["category", "name", "label"]),
      brands: salesInsightsSnapshotOptions(payload.brands, ["brand", "name", "label"]),
      channels: salesInsightsSnapshotOptions(payload.bannerBreakdown, ["dim"]),
      retailers: salesInsightsSnapshotOptions(payload.bannerBreakdown, ["dim"]),
      regions: salesInsightsSnapshotOptions(payload.regions, ["region", "name", "label"]),
      divisions: [],
      products: salesInsightsSnapshotOptions(payload.products, ["description", "product", "name", "label"])
    },
    metrics: {
      orderLines: rows, orders: 0, salesValue: sourceMetrics.salesValue, quantity: sourceMetrics.quantity,
      stores: client ? salesInsightsSnapshotNumber(monthly.at(-1)?.stores) : salesInsightsSnapshotNumber(storesCard.value || payload.summary?.store_count),
      reps: 0, averageOrderValue: averageUnitPrice, averageUnitsPerOrder: 0, averageMonthValue,
      mappedRows: rows, mappedPercent: 100, latestNewRecords: 0, missingRegionRows: 0, missingRepRows: 0, duplicateSourceRows: 0, existingRecords: rows
    },
    priorMetrics: { orderLines: rows, orders: 0, salesValue: sourceMetrics.priorSalesValue, quantity: sourceMetrics.priorQuantity, stores: 0, reps: 0 },
    charts: { byRegion, byRep, byManager: [], byStore, byProduct: [], bySku: [], byStatus: [], byClient: salesInsightsSnapshotBreakdown(rowsForPeriods(payload.clientMonthly, currentPeriods), ["client"]), byDivision: [], byChannel: byRetailer, byRetailer, byBanner: byRetailer, byBrand, byCategory, daily: monthly, monthly },
    priorCharts: { byRegion: salesInsightsSnapshotDimensionPriorBreakdown(payload.regionBreakdown), byRep: [], byManager: [], byStore: [], byProduct: [], bySku: [], byStatus: [], byClient: salesInsightsSnapshotBreakdown(rowsForPeriods(payload.clientMonthly, priorPeriods), ["client"]), byDivision: [], byChannel: salesInsightsSnapshotDimensionPriorBreakdown(payload.bannerBreakdown), byRetailer: salesInsightsSnapshotDimensionPriorBreakdown(payload.bannerBreakdown), byBanner: salesInsightsSnapshotDimensionPriorBreakdown(payload.bannerBreakdown), byBrand: salesInsightsSnapshotDimensionPriorBreakdown(payload.brandBreakdown), byCategory: priorByCategory, monthly: priorMonthly },
    recentOrders: [], unmapped: [], quality: { sourceRows: rows, uniqueSourceRows: rows, duplicateSourceRows: 0, newRecords: 0, existingRecords: rows, staleRowsRemoved: 0, fullMonthSnapshot: true, missingRegionRows: 0, missingRepRows: 0, missingOrderNumberRows: 0, mappedRows: rows, unmappedStoreCount: 0, reconciliation: null, storeMasterQuality: null }
  };
}

async function readSalesInsightsSnapshot() {
  const current = await db.collection(salesInsightsSnapshotCollection).doc(salesInsightsSnapshotCurrentId).get();
  if (!current.exists || !optionalText(current.data()?.storagePath, 500)) {
    throw new HttpsError("failed-precondition", "No Sales Insights snapshot is available yet. An administrator must run the historical Sales Insights refresh.");
  }
  const metadata = current.data();
  try {
    const [contents] = await getStorage().bucket().file(metadata.storagePath).download();
    const parsed = JSON.parse(contents.toString("utf8"));
    return { ...metadata, payload: parsed.payload || {} };
  } catch (error) {
    console.error("Unable to read Sales Insights snapshot", error);
    throw new HttpsError("internal", "The current Sales Insights snapshot could not be read.");
  }
}

function salesInsightsQueryParameters(value) {
  if (value == null) return {};
  if (typeof value !== "object" || Array.isArray(value)) throw new HttpsError("invalid-argument", "Sales Insights query parameters must be an object.");
  const params = {};
  for (const [key, raw] of Object.entries(value)) {
    if (!salesInsightsQueryParameterNames.has(key) || raw == null || raw === "") continue;
    if (typeof raw === "object" || typeof raw === "boolean") throw new HttpsError("invalid-argument", `Invalid Sales Insights query parameter: ${key}.`);
    if (key === "limit" || key === "top") {
      const number = Math.floor(Number(raw));
      if (!Number.isFinite(number)) throw new HttpsError("invalid-argument", `Invalid Sales Insights query parameter: ${key}.`);
      params[key] = Math.max(1, Math.min(number, 8000));
    } else {
      params[key] = optionalText(raw, 320);
    }
  }
  return params;
}

async function salesInsightsQueryEndpoint() {
  const configured = optionalText(process.env.SALES_INSIGHTS_QUERY_URL || salesInsightsQueryDefaultUrl, 600).replace(/\/$/, "");
  if (configured) return configured;
  if (salesInsightsQueryServiceUrl) return salesInsightsQueryServiceUrl;
  const projectId = process.env.GCLOUD_PROJECT || "meridain-nexus";
  const client = await googleAuth.getClient();
  const response = await client.request({
    url: `https://run.googleapis.com/v2/projects/${projectId}/locations/${salesInsightsPipelineSource.cloudRunLocation}/services/${salesInsightsPipelineSource.cloudRunQueryService}`,
    method: "GET"
  });
  const uri = optionalText(response.data?.uri, 600).replace(/\/$/, "");
  if (!uri) throw new Error("The Sales Insights query service does not have a Cloud Run URL.");
  salesInsightsQueryServiceUrl = uri;
  return uri;
}

async function querySalesInsightsMaster(route, params, masterPath) {
  const endpoint = await salesInsightsQueryEndpoint();
  const client = await salesInsightsQueryAuth.getIdTokenClient(endpoint);
  const response = await client.request({
    url: `${endpoint}/query`,
    method: "POST",
    data: { route, params, masterPath },
    timeout: 300000
  });
  return response.data;
}



async function findActiveSalesInsightsPipelineRun() {
  for (const status of ["queued", "running"]) {
    const active = await db.collection(salesInsightsPipelineSource.runsCollection).where("status", "==", status).limit(1).get();
    if (!active.empty) return { id: active.docs[0].id, ...active.docs[0].data() };
  }
  return null;
}

async function triggerSalesInsightsCloudRun(runRef, force = false) {
  try {
    const client = await googleAuth.getClient();
    const projectId = process.env.GCLOUD_PROJECT || "meridain-nexus";
    const response = await client.request({
      url: `https://run.googleapis.com/v2/projects/${projectId}/locations/${salesInsightsPipelineSource.cloudRunLocation}/jobs/${salesInsightsPipelineSource.cloudRunJob}:run`,
      method: "POST",
      data: {
        overrides: {
          containerOverrides: [{
            env: [
              { name: "SALES_INSIGHTS_RUN_ID", value: runRef.id },
              { name: "SALES_INSIGHTS_FORCE", value: force === true ? "true" : "false" }
            ]
          }]
        }
      }
    });
    const operation = optionalText(response.data?.name, 500);
    await runRef.set({
      status: "queued",
      cloudRunOperation: operation || null,
      triggeredAt: FieldValue.serverTimestamp(),
      message: "Cloud Run has been asked to mirror the SharePoint Sales Insights master into Firebase."
    }, { merge: true });
    return operation;
  } catch (error) {
    await runRef.set({
      status: "failed-to-start",
      failedAt: FieldValue.serverTimestamp(),
      message: optionalText(error?.message || error, 1000) || "Cloud Run could not start the Sales Insights pipeline."
    }, { merge: true });
    throw error;
  }
}

async function queueSalesInsightsPipelineRun({ trigger = "manual", actor = null, force = false } = {}) {
  const active = await findActiveSalesInsightsPipelineRun();
  if (active) return { runId: active.id, status: active.status, reused: true, operation: active.cloudRunOperation || null };
  const runId = `sales-insights-${Date.now()}-${crypto.randomUUID().slice(0, 12)}`;
  const runRef = db.collection(salesInsightsPipelineSource.runsCollection).doc(runId);
  await runRef.set({
    status: "queued",
    trigger,
    force: force === true,
    requestedBy: actor ? { uid: actor.uid || "", email: actor.email || "", name: actor.name || "" } : { uid: "", email: "scheduled", name: "Sales Insights scheduler" },
    createdAt: FieldValue.serverTimestamp(),
    message: "Waiting for the Sales Insights Cloud Run worker."
  });
  try {
    const operation = await triggerSalesInsightsCloudRun(runRef, force);
    return { runId, status: "queued", reused: false, operation };
  } catch (error) {
    throw new HttpsError("failed-precondition", `The Sales Insights Cloud Run worker could not be started: ${optionalText(error?.message || error, 700)}`);
  }
}




exports.getGeoRepSalesDashboard = onCall({
  timeoutSeconds: 120, memory: "1GiB",
  cors: ["https://meridian-nexus.web.app", "https://meridian-nexus.firebaseapp.com"]
}, async (request) => {
  requireOperator(request);
  const workspace = optionalText(request.data?.workspace, 24) || "sales";
  if (!["sales", "insights"].includes(workspace)) throw new HttpsError("invalid-argument", "Choose a valid sales workspace.");
  await requireNavigationPermission(request, workspace);
  const requestedPeriod = optionalText(request.data?.periodKey, 7);
  const periodKey = /^\d{4}-\d{2}$/.test(requestedPeriod) ? requestedPeriod : localDateParts(new Date(), "Africa/Johannesburg").date.slice(0, 7);
  const requestedWindow = Math.floor(Number(request.data?.windowMonths || 1));
  const windowMonths = workspace === "insights" && [1, 3, 6, 12].includes(requestedWindow) ? requestedWindow : 1;
  const startPeriodKey = salesDashboardPeriodKeyOffset(periodKey, windowMonths - 1);
  const priorEndPeriodKey = salesDashboardPeriodKeyOffset(periodKey, windowMonths);
  const priorStartPeriodKey = salesDashboardPeriodKeyOffset(periodKey, (windowMonths * 2) - 1);
  const filters = request.data?.filters || {};
  const [configDoc, snapshot, priorSnapshot, imports] = await Promise.all([
    db.collection("salesDashboardConfig").doc("current").get(),
    windowMonths > 1
      ? db.collection("salesTransactions").where("periodKey", ">=", startPeriodKey).where("periodKey", "<=", periodKey).limit(30000).get()
      : db.collection("salesTransactions").where("periodKey", "==", periodKey).limit(30000).get(),
    workspace === "insights"
      ? (windowMonths > 1
        ? db.collection("salesTransactions").where("periodKey", ">=", priorStartPeriodKey).where("periodKey", "<=", priorEndPeriodKey).limit(30000).get()
        : db.collection("salesTransactions").where("periodKey", "==", priorEndPeriodKey).limit(30000).get())
      : Promise.resolve(null),
    db.collection("salesTransactionImports").orderBy("createdAt", "desc").limit(6).get()
  ]);
  const source = snapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() }));
  const priorSource = priorSnapshot?.docs?.map((doc) => ({ id: doc.id, ...doc.data() })) || [];
  const optionValues = (field) => [...new Set(source.map((row) => salesDashboardCleanText(row[field], 120)).filter(Boolean))].sort((left, right) => left.localeCompare(right)).slice(0, 500);
  const selected = source.filter((row) => salesDashboardMatchesFilters(row, filters));
  const priorSelected = priorSource.filter((row) => salesDashboardMatchesFilters(row, filters));
  const totalValue = selected.reduce((total, row) => total + Number(row.value || 0), 0);
  const totalQuantity = selected.reduce((total, row) => total + Number(row.quantity || 0), 0);
  const priorValue = priorSelected.reduce((total, row) => total + Number(row.value || 0), 0);
  const priorQuantity = priorSelected.reduce((total, row) => total + Number(row.quantity || 0), 0);
  const daily = salesDashboardBreakdown(selected.filter((row) => row.periodKey === periodKey), "orderDate", 31).sort((left, right) => left.label.localeCompare(right.label));
  const monthly = salesDashboardBreakdown(selected, "periodKey", 24).sort((left, right) => left.label.localeCompare(right.label));
  const mappedRows = selected.filter((row) => row.mapped).length;
  const missingRegionRows = selected.filter((row) => !row.mapped || !salesDashboardCleanText(row.region) || row.region === "Unmapped").length;
  const missingRepRows = selected.filter((row) => row.repMissing === true || !salesDashboardCleanText(row.rep) || row.rep === "Unassigned").length;
  const latestImport = imports.docs.map((doc) => ({ id: doc.id, ...doc.data() })).find((item) => item.periodKey === periodKey) || null;
  const orderCount = new Set(selected.map((row) => row.orderNumber)).size;
  const recentOrders = [...selected]
    .sort((left, right) => `${right.orderDate}|${right.orderNumber}`.localeCompare(`${left.orderDate}|${left.orderNumber}`))
    .slice(0, 15)
    .map((row) => ({ orderDate: row.orderDate, orderNumber: row.orderNumber, storeName: row.storeName, region: row.region, rep: row.rep, sku: row.sku, product: row.product, banner: row.banner, channel: row.channel, quantity: row.quantity, value: row.value }));
  return {
    periodKey, startPeriodKey, windowMonths, config: configDoc.exists ? configDoc.data() : null, latestImport,
    priorPeriodKey: priorEndPeriodKey,
    priorStartPeriodKey,
    availableFilters: { regions: optionValues("region"), reps: optionValues("rep"), stores: optionValues("storeName"), skus: optionValues("sku"), products: optionValues("product"), managers: optionValues("manager"), statuses: optionValues("status"), clients: optionValues("client"), divisions: optionValues("division"), channels: optionValues("channel"), retailers: optionValues("banner"), banners: optionValues("banner"), brands: optionValues("brand"), categories: optionValues("category") },
    metrics: {
      orderLines: selected.length, orders: orderCount, salesValue: totalValue, quantity: totalQuantity,
      stores: new Set(selected.map((row) => row.storeName)).size, reps: new Set(selected.map((row) => row.rep)).size,
      averageOrderValue: orderCount ? totalValue / orderCount : 0, averageUnitsPerOrder: orderCount ? totalQuantity / orderCount : 0,
      mappedRows, mappedPercent: selected.length ? (mappedRows / selected.length) * 100 : 0,
      latestNewRecords: Number(latestImport?.newRecords || 0),
      missingRegionRows,
      missingRepRows,
      duplicateSourceRows: Number(latestImport?.duplicateSourceRows || 0),
      existingRecords: Number(latestImport?.existingRecords || 0),
      reconciled: latestImport?.reconciliation?.reconciled === true
    },
    priorMetrics: {
      orderLines: priorSelected.length, orders: new Set(priorSelected.map((row) => row.orderNumber)).size,
      salesValue: priorValue, quantity: priorQuantity,
      stores: new Set(priorSelected.map((row) => row.storeName)).size,
      reps: new Set(priorSelected.map((row) => row.rep)).size
    },
    charts: {
      byRegion: salesDashboardBreakdown(selected, "region"), byRep: salesDashboardBreakdown(selected, "rep"), byManager: salesDashboardBreakdown(selected, "manager"),
      byStore: salesDashboardBreakdown(selected, "storeName"), byProduct: salesDashboardBreakdown(selected, "product"), bySku: salesDashboardBreakdown(selected, "sku"),
      byStatus: salesDashboardBreakdown(selected, "status"), byClient: salesDashboardBreakdown(selected, "client"), byDivision: salesDashboardBreakdown(selected, "division"), byChannel: salesDashboardBreakdown(selected, "channel"), byRetailer: salesDashboardBreakdown(selected, "banner", 20), byBanner: salesDashboardBreakdown(selected, "banner", 20), byBrand: salesDashboardBreakdown(selected, "brand"), byCategory: salesDashboardBreakdown(selected, "category"), daily, monthly
    },
    priorCharts: {
      byRegion: salesDashboardBreakdown(priorSelected, "region"), byRep: salesDashboardBreakdown(priorSelected, "rep"), byManager: salesDashboardBreakdown(priorSelected, "manager"),
      byStore: salesDashboardBreakdown(priorSelected, "storeName"), byProduct: salesDashboardBreakdown(priorSelected, "product"), bySku: salesDashboardBreakdown(priorSelected, "sku"),
      byStatus: salesDashboardBreakdown(priorSelected, "status"), byClient: salesDashboardBreakdown(priorSelected, "client"), byDivision: salesDashboardBreakdown(priorSelected, "division"), byChannel: salesDashboardBreakdown(priorSelected, "channel"),
      byRetailer: salesDashboardBreakdown(priorSelected, "banner", 20), byBanner: salesDashboardBreakdown(priorSelected, "banner", 20), byBrand: salesDashboardBreakdown(priorSelected, "brand"),
      byCategory: salesDashboardBreakdown(priorSelected, "category"), monthly: salesDashboardBreakdown(priorSelected, "periodKey", 24).sort((left, right) => left.label.localeCompare(right.label))
    },
    recentOrders,
    unmapped: salesDashboardBreakdown(selected.filter((row) => !row.mapped), "storeName", 20),
    quality: {
      sourceRows: Number(latestImport?.sourceRows || 0),
      uniqueSourceRows: Number(latestImport?.uniqueSourceRows || 0),
      duplicateSourceRows: Number(latestImport?.duplicateSourceRows || 0),
      newRecords: Number(latestImport?.newRecords || 0),
      existingRecords: Number(latestImport?.existingRecords || 0),
      staleRowsRemoved: Number(latestImport?.staleRowsRemoved || 0),
      fullMonthSnapshot: latestImport?.fullMonthSnapshot === true,
      missingRegionRows,
      missingRepRows,
      missingOrderNumberRows: Number(latestImport?.missingOrderNumberRows || 0),
      mappedRows,
      unmappedStoreCount: Number(latestImport?.unmappedStoreCount || new Set(selected.filter((row) => !row.mapped).map((row) => row.storeCode || row.storeName)).size),
      reconciliation: latestImport?.reconciliation || null,
      storeMasterQuality: latestImport?.storeMasterQuality || null
    }
  };
});

exports.getGeoRepSalesDrilldown = onCall({
  timeoutSeconds: 120, memory: "1GiB",
  cors: ["https://meridian-nexus.web.app", "https://meridian-nexus.firebaseapp.com"]
}, async (request) => {
  await requireNavigationPermission(request, "sales");
  const requestedPeriod = optionalText(request.data?.periodKey, 7);
  const periodKey = /^\d{4}-\d{2}$/.test(requestedPeriod) ? requestedPeriod : localDateParts(new Date(), "Africa/Johannesburg").date.slice(0, 7);
  const metric = optionalText(request.data?.metric, 40) || "sales-value";
  const allowedMetrics = new Set(["sales-value", "orders", "units", "average-order", "stores", "reps", "mapped", "latest-import"]);
  if (!allowedMetrics.has(metric)) throw new HttpsError("invalid-argument", "Select a valid sales metric.");
  const filters = request.data?.filters || {};
  const requestedPage = Math.max(1, Math.floor(Number(request.data?.page || 1)));
  const [snapshot, imports] = await Promise.all([
    db.collection("salesTransactions").where("periodKey", "==", periodKey).limit(30000).get(),
    db.collection("salesTransactionImports").orderBy("createdAt", "desc").limit(6).get()
  ]);
  const selected = snapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() })).filter((row) => salesDashboardMatchesFilters(row, filters));
  const latestImport = imports.docs.map((doc) => ({ id: doc.id, ...doc.data() })).find((item) => item.periodKey === periodKey) || null;
  return { periodKey, metric, ...salesDashboardDrilldown(metric, selected, latestImport, requestedPage) };
});

const trainingHubSource = {
  hostname: "meridiangroupza.sharepoint.com",
  sitePath: "/sites/PowerBI9-PowerBI-PG",
  folderPath: "Power BI - PG/Training"
};

function trainingHubText(value, limit = 240) {
  return String(value == null ? "" : value).replace(/\s+/g, " ").trim().slice(0, limit);
}

function trainingHubNumber(value) {
  const number = Number(String(value == null ? "" : value).replace(/[^\d.-]/g, ""));
  return Number.isFinite(number) ? number : 0;
}

function trainingHubNameFromFile(value) {
  return trainingHubText(value, 180).replace(/\.xlsx?$/i, "").replace(/\s*[-_]?\s*training\s*(leaderboard|program(?:me)?|tracker)?\s*$/i, "").trim() || "Training module";
}

function trainingHubStatus(value) {
  const status = trainingHubText(value, 80).toLowerCase();
  if (status.includes("pass")) return "Passed";
  if (status.includes("not") && status.includes("start")) return "Not Started";
  if (status.includes("progress")) return "In Progress";
  if (status.includes("fail")) return "Failed";
  return status ? trainingHubText(value, 80) : "Unknown";
}

async function trainingHubFiles(accessToken, driveId, folderPath, depth = 0) {
  const response = await graphRequest(accessToken, `/drives/${driveId}/root:/${encodeGraphPath(folderPath)}:/children?$select=id,name,file,folder,lastModifiedDateTime,webUrl&$top=200`);
  const entries = Array.isArray(response?.value) ? response.value : [];
  const files = entries.filter((item) => item?.file && /\.xlsx$/i.test(String(item.name || "")) && !/^~\$/.test(String(item.name || "")))
    .map((item) => ({ ...item, relativePath: `${folderPath}/${item.name}` }));
  if (depth >= 3) return files;
  const nested = await Promise.all(entries.filter((item) => item?.folder).map((item) => trainingHubFiles(accessToken, driveId, `${folderPath}/${item.name}`, depth + 1)));
  return files.concat(...nested);
}

async function trainingHubModuleFromFile(context, file) {
  const buffer = await downloadSharePointPathBuffer(context.accessToken, context.drive.id, file.relativePath, `Training workbook ${file.name}`);
  const workbook = new ExcelJS.Workbook();
  await workbook.xlsx.load(buffer);
  const sheet = workbook.getWorksheet("Sheet1") || workbook.worksheets[0];
  if (!sheet) throw new Error("The workbook has no worksheet.");
  const rows = [];
  sheet.eachRow({ includeEmpty: false }, (row) => rows.push(row.values.slice(1)));
  if (rows.length < 2) throw new Error("The workbook has no learner rows.");
  const headers = (rows[0] || []).map((value) => trainingHubText(value, 160).toLowerCase());
  const at = (name) => headers.indexOf(name);
  const index = {
    name: at("user name"), manager: at("manager"), region: at("region"), type: at("rep type"),
    total: at("total lessons"), done: at("lessons completed"), score: at("quiz score"), status: at("course session status"),
    course: at("course name"), code: at("course code"), userCode: at("user code"), start: at("course start date"), end: at("course end date")
  };
  if (index.name < 0 || index.done < 0) throw new Error("Sheet1 does not contain the expected LMS learner and lesson columns.");
  const cell = (row, position) => position >= 0 ? row[position] : "";
  let course = ""; let code = ""; let start = ""; let end = "";
  const learners = rows.slice(1).map((row) => {
    const name = trainingHubText(cell(row, index.name), 160);
    if (!name) return null;
    if (!course) {
      course = trainingHubText(cell(row, index.course), 180);
      code = trainingHubText(cell(row, index.code), 120);
      start = trainingHubText(cell(row, index.start), 80);
      end = trainingHubText(cell(row, index.end), 80);
    }
    return {
      name, code: trainingHubText(cell(row, index.userCode), 80), manager: trainingHubText(cell(row, index.manager), 120) || "Unassigned", region: trainingHubText(cell(row, index.region), 120) || "Unassigned", type: trainingHubText(cell(row, index.type), 80) || "Unassigned",
      total: trainingHubNumber(cell(row, index.total)), done: trainingHubNumber(cell(row, index.done)), score: trainingHubNumber(cell(row, index.score)), status: trainingHubStatus(cell(row, index.status))
    };
  }).filter(Boolean);
  if (!learners.length) throw new Error("The workbook did not contain any named learners.");
  return { id: file.id, name: trainingHubNameFromFile(file.name), course, code, start, end, modifiedAt: file.lastModifiedDateTime || "", sourceName: file.name, sourceUrl: file.webUrl || "", learners };
}

exports.getTrainingHubDashboard = onCall({
  secrets: [sharePointTenantId, sharePointClientId, sharePointClientSecret], timeoutSeconds: 180, memory: "1GiB", cors: ["https://meridian-nexus.web.app", "https://meridian-nexus.firebaseapp.com"]
}, async (request) => {
  await requireNavigationPermission(request, "training");
  const accessToken = await sharePointAccessToken();
  const site = await graphRequest(accessToken, `/sites/${trainingHubSource.hostname}:${trainingHubSource.sitePath}?$select=id,webUrl`);
  const drive = await graphRequest(accessToken, `/sites/${site.id}/drive?$select=id,name,webUrl`);
  const context = { accessToken, site, drive };
  const files = await trainingHubFiles(accessToken, drive.id, trainingHubSource.folderPath);
  if (!files.length) throw new HttpsError("not-found", "No Training Hub workbooks were found in Power BI - PG/Training.");
  const results = await Promise.all(files.map(async (file) => {
    try { return { module: await trainingHubModuleFromFile(context, file) }; }
    catch (error) { return { error: `${file.name}: ${String(error?.message || error).slice(0, 240)}` }; }
  }));
  const modules = results.map((result) => result.module).filter(Boolean).sort((left, right) => String(right.modifiedAt).localeCompare(String(left.modifiedAt)));
  const errors = results.map((result) => result.error).filter(Boolean);
  if (!modules.length) throw new HttpsError("failed-precondition", `Training workbooks were found but could not be read. ${errors[0] || ""}`.trim());
  return { source: { provider: "SharePoint", folder: trainingHubSource.folderPath, siteUrl: site.webUrl || "", refreshedAt: new Date().toISOString() }, modules, errors };
});

const stockFixDashboardSource = {
  hostname: "meridiangroupza.sharepoint.com",
  sitePath: "/sites/MeridianNexus",
  dataFolderPath: "Stock Fix/Reporting/dashboard-data",
  sourceFolderUrl: "https://meridiangroupza.sharepoint.com/sites/MeridianNexus/Shared%20Documents/Forms/AllItems.aspx?id=%2Fsites%2FMeridianNexus%2FShared%20Documents%2FStock%20Fix&viewid=07363d44%2D959c%2D4333%2D9a6d%2De18024fb140d"
};

// Nexus keeps Stock Fix source files in Firebase Storage and only stores the
// compact, queryable weekly snapshot in Firestore. Firestore is deliberately
// not used for the full inventory fact table: a weekly source can contain
// millions of rows and must remain a file-backed dataset.
const stockFixFirebaseSource = {
  uploadsCollection: "stockFixUploads",
  weeksCollection: "stockFixWeeks",
  storagePrefix: "stockfix-source/",
  maxCompressedBytes: 250 * 1024 * 1024,
  maxExpandedBytes: 900 * 1024 * 1024
};

// Adoption is a separate, people-level report. It deliberately has its own
// source prefix and Firestore hierarchy so publishing it cannot affect the
// Stock Fix task feed or the Cloud Run weekly pipeline.
const stockFixAdoptionSource = {
  weeksCollection: "stockFixAdoptionWeeks",
  storagePrefix: "stockfix-adoption-source/",
  maxBytes: 25 * 1024 * 1024
};

function stockFixAdoptionStoragePath(value, uploadId) {
  const storagePath = optionalText(value, 500);
  const expectedPrefix = `${stockFixAdoptionSource.storagePrefix}${uploadId}/`;
  if (!storagePath.startsWith(expectedPrefix) || storagePath.slice(expectedPrefix.length).includes("/")) {
    throw new HttpsError("invalid-argument", "The Adoption workbook must be uploaded through the current Nexus upload.");
  }
  if (!/\.xlsx$/i.test(storagePath)) throw new HttpsError("invalid-argument", "The Adoption source must be an XLSX workbook.");
  return storagePath;
}

function stockFixAdoptionSourceName(value) {
  const sourceName = optionalText(value, 240);
  if (!/\.xlsx$/i.test(sourceName)) throw new HttpsError("invalid-argument", "Upload an XLSX Adoption workbook.");
  return sourceName;
}

function stockFixAdoptionText(value) {
  return String(value ?? "").trim();
}

function stockFixAdoptionNumber(value) {
  const parsed = Number(String(value ?? "").replace(/[^0-9.-]/g, ""));
  return Number.isFinite(parsed) ? parsed : 0;
}

function stockFixAdoptionPercent(value) {
  const parsed = stockFixAdoptionNumber(value);
  if (!Number.isFinite(parsed)) return 0;
  return Math.max(0, Math.min(100, parsed <= 1 ? parsed * 100 : parsed));
}

function stockFixAdoptionRole(type) {
  const normalized = String(type || "").toUpperCase();
  if (normalized.includes("MERCH")) return "Merchandiser";
  if (normalized.includes("REP")) return "Rep";
  return "Other";
}

async function stockFixAdoptionRowsFromWorkbook(buffer) {
  const workbook = new ExcelJS.Workbook();
  await workbook.xlsx.load(buffer);
  const worksheet = workbook.worksheets.find((sheet) => sheet.rowCount > 1);
  if (!worksheet) throw new HttpsError("failed-precondition", "The Adoption workbook has no readable worksheet.");
  const headers = new Map();
  worksheet.getRow(1).eachCell({ includeEmpty: false }, (cell, columnNumber) => {
    headers.set(String(cell.text || "").trim().toLowerCase(), columnNumber);
  });
  const required = ["resource", "resource type", "region", "manager", "captures", "adoption"];
  const missing = required.filter((header) => !headers.has(header));
  if (missing.length) throw new HttpsError("failed-precondition", `The Adoption workbook is missing: ${missing.join(", ")}.`);
  const rows = [];
  worksheet.eachRow({ includeEmpty: false }, (row, rowNumber) => {
    if (rowNumber === 1) return;
    const resource = stockFixAdoptionText(row.getCell(headers.get("resource")).text);
    if (!resource) return;
    const resourceType = stockFixAdoptionText(row.getCell(headers.get("resource type")).text) || "Unclassified";
    const region = stockFixAdoptionText(row.getCell(headers.get("region")).text) || "Unassigned";
    const manager = stockFixAdoptionText(row.getCell(headers.get("manager")).text) || "Unassigned";
    const captures = stockFixAdoptionNumber(row.getCell(headers.get("captures")).value);
    const adoption = stockFixAdoptionPercent(row.getCell(headers.get("adoption")).value);
    rows.push({ resource, resourceType, region, manager, captures, adoption, role: stockFixAdoptionRole(resourceType) });
  });
  if (!rows.length) throw new HttpsError("failed-precondition", "The Adoption workbook contains no usable resource rows.");
  return rows;
}

function stockFixAdoptionBreakdown(rows, field) {
  const groups = new Map();
  for (const row of rows) {
    const label = String(row[field] || "Unassigned");
    const entry = groups.get(label) || { label, total: 0, active: 0, captures: 0 };
    entry.total += 1;
    entry.active += Number(row.adoption || 0) > 0 ? 1 : 0;
    entry.captures += Number(row.captures || 0);
    groups.set(label, entry);
  }
  return [...groups.values()].map((entry) => ({
    ...entry,
    adoption: entry.total ? Math.round((entry.active / entry.total) * 1000) / 10 : 0
  })).sort((left, right) => right.total - left.total || right.captures - left.captures || left.label.localeCompare(right.label));
}

function stockFixAdoptionMetrics(rows) {
  const total = rows.length;
  const active = rows.filter((row) => Number(row.adoption || 0) > 0).length;
  const roleMetrics = (role) => {
    const roleRows = rows.filter((row) => row.role === role);
    const roleActive = roleRows.filter((row) => Number(row.adoption || 0) > 0).length;
    return {
      total: roleRows.length,
      active: roleActive,
      adoption: roleRows.length ? Math.round((roleActive / roleRows.length) * 1000) / 10 : 0
    };
  };
  return {
    resources: total,
    active,
    adoption: total ? Math.round((active / total) * 1000) / 10 : 0,
    captures: rows.reduce((sum, row) => sum + Number(row.captures || 0), 0),
    rep: roleMetrics("Rep"),
    merchandiser: roleMetrics("Merchandiser")
  };
}

function stockFixAdoptionFilters(rows) {
  const values = (field) => [...new Set(rows.map((row) => String(row[field] || "")).filter(Boolean))].sort((left, right) => left.localeCompare(right));
  return { resourceTypes: values("resourceType"), regions: values("region"), managers: values("manager") };
}

function stockFixAdoptionDashboard(rows, filters = {}) {
  const search = String(filters.search || "").trim().toLowerCase();
  const filtered = rows.filter((row) => (
    (!filters.resourceType || row.resourceType === filters.resourceType)
    && (!filters.region || row.region === filters.region)
    && (!filters.manager || row.manager === filters.manager)
    && (!search || [row.resource, row.resourceType, row.region, row.manager].join(" ").toLowerCase().includes(search))
  ));
  return {
    metrics: stockFixAdoptionMetrics(filtered),
    charts: {
      byResourceType: stockFixAdoptionBreakdown(filtered, "resourceType"),
      byRegion: stockFixAdoptionBreakdown(filtered, "region"),
      byManager: stockFixAdoptionBreakdown(filtered, "manager")
    },
    resources: [...filtered].sort((left, right) => Number(right.captures || 0) - Number(left.captures || 0) || left.resource.localeCompare(right.resource)).slice(0, 120),
    shownRows: filtered.length
  };
}

const stockFixPipelineSource = {
  runsCollection: "stockFixPipelineRuns",
  storagePrefix: "stockfix-pipeline-input/",
  cloudRunLocation: "us-central1",
  cloudRunJob: "stockfix-pipeline",
  bucketName: process.env.FIREBASE_STORAGE_BUCKET || "meridain-nexus.firebasestorage.app",
  maxSources: 40,
  maxSourceBytes: 250 * 1024 * 1024
};

// The SharePoint export is the verified output of the legacy Stock Fix task
// generator. Nexus reads it only, then owns the Storage copy, Cloud Run import,
// Firestore snapshot and field-task workflow from that point onward.
const stockFixSharePointAutomationSource = {
  statusCollection: "stockFixAutomation",
  statusDocument: "sharepointWeeklyTaskExports",
  healthDocument: "stockfix-sharepoint-task-exports",
  folderPath: "Stock Fix/Reporting/Historical feedback",
  filePattern: /^stockfix-weekly-export-(\d{4}-\d{2}-\d{2})\.(?:csv|xlsx)$/i,
  minStableAgeMs: 10 * 60 * 1000,
  maxAttemptsForSameSource: 3
};

// The operational Stock Fix product is deliberately separate from the compact
// dashboard snapshots above. These records are the Nexus-owned replacement for
// the legacy Replit/Neon task tables. Source workbooks and photos stay in
// Storage; Firestore holds the task state, capture history and assignments.
